const icon=n=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${ICON[n]||ICON.arrow}"/></svg>`;
const B=(label,a,id='',cl='',more='')=>`<button type="button" class="btn ${cl}" data-a="${a}" data-id="${esc(id)}" ${more}>${label}</button>`;
function portrait(id='secretary',size='',expression){const p=C.people[id]||C.people.secretary;const row=expression??characterMood(id);return `<span class="avatar ${size}" role="img" aria-label="${esc(p.name)}" style="background-image:url('${asset(p.sheet)}');background-position:${p.col*25}% ${row*100/3}%"></span>`;}
function person(id,line='',size=''){const p=C.people[id]||C.people.secretary;return `<div class="person">${portrait(id,size)}<div><strong>${esc(p.name)}</strong><div class="role">${esc(p.role)}</div>${line?`<small>${esc(line)}</small>`:''}</div></div>`;}
const I=window.HDInsights,P=window.HDPlanning;let guide=null,guideTimer,autoTimer;
let choiceDraft=null,timingDraft=null,workTimer=null;let S=null,view='scene',mapWorld=false,modalKind='',draft=[],activeTask=null,remoteTask=false,pending=null,returnFocus=null,toastTimer,started=false;
const KEY='huadong-ceo-v8-save',OPTIONS='huadong-ceo-v8-options',HISTORY='huadong-ceo-v8-history';let prefs={music:.25,effects:.4,environment:.32,muted:false};
try{const p=JSON.parse(localStorage.getItem(OPTIONS)||'{}');for(const k of ['music','effects','environment'])if(Number.isFinite(p[k]))prefs[k]=Math.min(1,Math.max(0,p[k]));if(typeof p.muted==='boolean')prefs.muted=p.muted;}catch{}
sound.levels(prefs.music,prefs.effects,prefs.muted,prefs.environment);
const dialog=$('#dialog');
function toast(text,error=false){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').className='toast visible'+(error?' error':'');toastTimer=setTimeout(()=>$('#toast').className='toast',6500);}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(E.save(S)));if(S.ending){let h=JSON.parse(localStorage.getItem(HISTORY)||'[]');const item={seed:S.seed,id:S.ending.id,title:S.ending.title,day:S.day,cash:S.cash,actions:S.actions.length};if(!h.some(x=>x.seed===item.seed&&x.cash===item.cash&&x.day===item.day&&x.id===item.id)){h.push(item);localStorage.setItem(HISTORY,JSON.stringify(h.slice(-20)));}}}catch{toast('此浏览器未能保存进度，请在设置中导出存档。',true);}}
function runOld(action,feedback=true){try{const old=S;S=E.dispatch(S,action);if(old.phase==='day'&&S.phase==='night'&&['task','event'].includes(action.type)){sceneHold={place:old.place,city:old.city};clearTimeout(ackTimer);ackTimer=setTimeout(()=>{sceneHold=null;if(started)render();},1500);}persist();close();if(S.ending)view='ending';else if(['travel','visit'].includes(action.type)||old.phase!==S.phase)view='scene';if(guide?.task&&((action.type==='task'&&action.id===guide.task)||(S.completed[guide.task]&&!E.available(S,C.taskById[guide.task]))))guide=null;if(guide?.report&&action.type==='readReport')guide=null;if(guide?.event&&action.type==='readEvent')guide=null;render();if(!['readReport','readEvent','readMessage'].includes(action.type))window.scrollTo({top:0});if(feedback&&!['readReport','readEvent','readMessage'].includes(action.type))toast(S.log.at(-1)?.title||'进度已保存。');if(S.cash>old.cash)sound.effect('cash');else if(['visit','travel'].includes(action.type))sound.effect('door');else if(!['readReport','readEvent','readMessage'].includes(action.type))sound.effect('confirm');if(!['readReport','readEvent','readMessage'].includes(action.type)){clearTimeout(autoTimer);autoTimer=setTimeout(()=>afterAction(old,action),260);}setTimeout(refreshGuide,60);if(action.type==='sleep'||action.type==='acceptOffer')maybePriority();return true;}catch(e){const box=$('#modal-error');if(dialog.open&&box){box.textContent=e.message;box.scrollIntoView({block:'nearest'});}else toast(e.message,true);sound.effect('alert');return false;}}
function closeLegacy(){const previousKind=modalKind;if(dialog.open)dialog.close();clearTimeout(workTimer);modalKind='';if(returnFocus?.isConnected)returnFocus.focus({preventScroll:true});setTimeout(()=>refreshGuide(false),50);}
function modalLegacy(title,body,{wide=false,kicker='华东智行 · CEO工作台',kind=''}={}){inputBoundary();choiceDraft=null;returnFocus=document.activeElement;modalKind=kind;dialog.className='dialog'+(wide?' wide':'')+(kind==='event'?' letter-dialog':'');dialog.innerHTML=`<div class="dialog-head"><div><div class="kicker">${esc(kicker)}</div><h2 id="modal-title">${esc(title)}</h2></div><button class="icon-btn" data-a="close" aria-label="关闭窗口">${icon('close')}</button></div><div class="dialog-body">${body}<div id="modal-error" class="dialog-error" role="alert"></div></div>`;if(!dialog.open)dialog.showModal();dialog.querySelector('.dialog-body').scrollTop=0;setTimeout(refreshGuide,40);}
function countPendingLegacy(){return S.events.filter(e=>['open','report'].includes(e.status)).length+Object.values(S.reports).filter(r=>!r.read).length;}
function controls(){if(S.ending)return '';return `<nav class="bottomnav" aria-label="主要功能"><button data-a="scene" class="${view!=='map'?'active':''}">${icon('building')}现场</button><button data-a="phone">${icon('phone')}手机${countPending()?`<span class="badge">${countPending()}</span>`:''}</button><button data-a="company">${icon('chart')}经营</button></nav><button class="secretary-fab" data-a="secretary" aria-label="联系秘书许知微，让她带路">${portrait('secretary')}<span class="fab-label">许知微<small>${guide?'正在为你带路':'不知道下一步？'}</small></span></button>`;}
function header(){const g=E.goal(S);return `<header class="topbar"><div class="brand"><span class="brand-mark">华</span><div><div class="brand-title">华东智行</div></div></div><div class="daybox"><div class="number">${String(S.day).padStart(2,'0')}</div><div><small>/ 25天 · ${S.phase==='day'?'白天':'夜晚'}</small><div class="slots" ${S.ending?'hidden':''} aria-label="${S.ending?'本轮结束':'白天剩余'+S.slots+'次行动，共3次'}">${[1,2,3].map(n=>`<i class="${S.slots>=n?'on':''}"></i>`).join('')}</div></div></div><div class="cashbox"><span>可用现金</span><strong class="number">${S.cash}</strong><small>万</small></div><button class="icon-btn" data-a="settings" aria-label="设置与存档">${icon('settings')}</button></header><div class="mission"><span class="mission-mark">${S.ending?'经营结局':S.phase==='night'?'夜间简报':'当前任务'}</span><div class="grow"><div class="mission-title">${esc(g.title)}</div><small>${S.ending?'本轮已结束，可以回看决定与实际结果。':S.phase==='night'?(S.day>=25?'最后一晚，核对报告、资金与未决事项。':'今天的结果和明天的风险，由许知微为你整理。'):esc(g.text)}</small></div><span class="action-count">${S.ending?'本轮结束':S.phase==='day'?S.slots+'次行动':S.nightUsed?'今晚审批已用':'可审批1次'}</span></div>`;}
function unreadReportRows(place){return Object.values(S.reports).filter(r=>!r.read&&S.phase==='night'&&(!place||C.taskById[r.id]?.place===place)).map(r=>`<button class="task-row" data-a="report" data-id="${r.id}" ${!r.read&&S.phase==='day'?'disabled':''}>${icon('folder')}<div><strong>${esc(r.title)}</strong><small>新报告 · 免费阅读</small></div><span class="arrow">›</span></button>`).join('');}
function taskRow(t,index=0,remote=false){const job=S.jobs.find(j=>j.task===t.id&&['queued','running'].includes(j.status));return `<button class="task-row" data-a="task" data-id="${t.id}" data-remote="${remote?'1':'0'}"><span class="task-number">${String(index+1).padStart(2,'0')}</span><div class="grow"><strong>${esc(t.title)}</strong><small>${job?'第'+job.due+'天夜晚交报告':remote?'可远程安排 · 使用1次行动':t.type==='finish'?'提交当前经营结果':'先看方案与代价 · 暂不耗时'}</small></div><span class="arrow">›</span></button>`;}
function placeButtons(city){return Object.entries(C.places).filter(([id,p])=>p.city===city&&!['home','apartment','hq'].includes(id)).map(([id,p])=>`<button class="${S.place===id?'selected':''}" data-a="placeInfo" data-id="${id}">${esc(p.name)}</button>`).join('');}
function renderSceneLegacy(){const atNight=S.phase==='night',p=C.places[S.place]||C.places.hq,scene=atNight?(['suzhou','shenzhen','chengdu'].includes(S.city)?'home':'apartment'):p.scene;
const title=atNight?(S.city==='suzhou'?'家中书房':C.cities[S.city].name+' · 夜间住处'):p.name;
const active=E.tasksAt(S,S.place),unread=Object.values(S.reports).filter(r=>!r.read&&C.taskById[r.id]?.place===S.place);
const hotspots=S.place==='hq'&&!atNight?Object.entries(C.places).filter(([,p])=>p.x).map(([id,p])=>`<button class="hotspot ${E.tasksAt(S,id).length?'active':''}" style="left:${p.x}%;top:${p.y}%" data-a="placeInfo" data-id="${id}" data-place="${id}">${esc(p.name.replace('会议室','').replace('资料室','部'))}</button>`).join(''):atNight?`<button class="hotspot" style="left:48%;top:65%" data-a="company">电脑 · 夜间简报</button><button class="hotspot" style="left:62%;top:81%" data-a="phone">手机 · 待办</button>`:'';
let aside;
if(atNight){const b=I.finances(S),f=I.forecast(S);aside=`${person('secretary')}<h2 class="night-title">今天，我们走到这里</h2><div class="mini-metrics"><div><strong>${b.today>0?'+':''}${b.today}</strong><small>今日现金 / 万</small></div><div><strong>${S.jobs.filter(j=>['queued','running'].includes(j.status)).length}</strong><small>执行中</small></div><div><strong>${countPending()}</strong><small>可处理事项</small></div></div>${progressTrack()}${nightReports().length?'<button class="btn primary full" data-v7="resumeReports">继续听完今晚的'+nightReports().length+'份报告</button>':''}<button class="btn ghost full" data-v6="capital">${S.market.lastTrade===S.day?'今晚已交易 · 查看行情':'夜间交易 · 免费 · 仅1次'}</button>${tomorrowCard()}<div class="rail-label">需要留意的风险</div>${f.slice(0,2).map(r=>riskCard(r,true)).join('')}${B('查看经营图与风险预测','company','','ghost full')}${B(S.day>=25?'完成今晚复盘':'休息，进入第'+(S.day+1)+'天','sleep','','primary full','style="margin-top:12px"')}`;}
else if(S.place==='hq'){aside=`${priorityCard()}${progressTrack()}`;}
else{aside=`${person(p.person)}<div class="quote">${esc(contextLine(p.person))}</div>${sceneNext()}${S.place==='partner'&&S.offer&&!S.completed.contract?B('审议伙伴还价','offer','','primary full'):''}<div class="rail-label">现在可以决定 <span>${active.length}项</span></div>${active.filter(t=>t.id===E.priority(S).task).map((t,i)=>taskRow(t,i)).join('')}${active.some(t=>t.id!==E.priority(S).task)?'<details class="other-work"><summary>其他可做的事（按需要展开）</summary>'+active.filter(t=>t.id!==E.priority(S).task).map((t,i)=>taskRow(t,i)).join('')+'</details>':''}${active.length&&!active.some(t=>t.id===E.priority(S).task)?B('不确定顺序？问问秘书','secretary','','ghost full'):''}${unreadReportRows(S.place)}${!active.length&&!unread.length?waitingCard():''}<details><summary>这个部门还负责什么</summary>${C.tasks.filter(t=>t.place===S.place&&!E.available(S,t)).map(t=>`<div class="compact-duty"><b>${esc(t.title)}</b><small>${esc(E.reason(S,t)||'根据当前阶段安排')}</small></div>`).join('')||'<p>当前职责已经展示在上方。</p>'}</details>`;}
return `<div class="play-grid"><section class="stage"><div class="stage-head"><div><small>${esc(C.cities[S.city].name)} · ${atNight?'夜间':'公司现场'}</small><h1>${esc(title)}</h1></div>${atNight?'':B(icon('map')+'选择地点','map','','ghost')}</div><div class="scene-art"><div class="scene-loading" aria-hidden="true">场景正在展开…</div><img src="${asset(scene)}" alt="${esc(title)}的商务场景" fetchpriority="high">${sceneFeedback(S.place,atNight)}${hotspots}<div class="scene-caption">${atNight?'夜间阅读免费 · '+(S.nightUsed?'今晚审批已用完':'可处理1项紧急审批'):S.place==='hq'?'点击房间 · 免费了解职责':'阅读方案免费 · 决定后使用1次行动'}</div></div>${atNight?'':`<p class="scene-foot">${S.place==='hq'?'苏州负责统筹，深圳与成都负责研发，新加坡连接伙伴与客户。':'用“选择地点”切换部门或城市；手机中可委派远程工作。'}</p>`}</section><aside class="rail">${aside}${!atNight?B('结束白天，回到住处','endDay','','ghost full','style="margin-top:22px"'):''}</aside></div>`;}
function renderMap(){const vb=mapWorld?'0 5 360 160':'253 35 85 68',r=mapWorld?1.1:.65;const paths=window.HDGeo.map(g=>`<path class="map-country ${['China','Malaysia','Japan','Singapore'].includes(g.name)?'key':''}" d="${g.d}"></path>`).join('');const labels={suzhou:[3,-2],shenzhen:[3,1],chengdu:[-9,-3],singapore:[4,5],malaysia:[-13,0],japan:[3,-2]};const nodes=Object.entries(C.cities).map(([id,c])=>{const x=c.lon+180,y=90-c.lat,[dx,dy]=labels[id];return `<g data-a="city" data-id="${id}" tabindex="0" role="button" aria-label="查看${c.name}"><circle class="map-node" cx="${x}" cy="${y}" r="${r}"/><path class="map-route" d="M${x} ${y}l${dx} ${dy}"/><text class="map-label" x="${x+dx}" y="${y+dy-.4}">${c.name}${id===S.city?' · 你在这里':''}</text><rect class="map-click" x="${Math.min(x-2.5,x+dx-1)}" y="${Math.min(y-2.5,y+dy-3)}" width="${Math.abs(dx)+17}" height="${Math.abs(dy)+6}"/></g>`;}).join('');const start=C.cities.suzhou;const routes=['shenzhen','chengdu','singapore','japan'].map(id=>{const c=C.cities[id];return `<path class="map-route" d="M${start.lon+180} ${90-start.lat}Q${(start.lon+c.lon)/2+185} ${90-(start.lat+c.lat)/2-4} ${c.lon+180} ${90-c.lat}"/>`;}).join('');return `<div class="play-grid"><section class="stage"><div class="stage-head"><div><div class="kicker">GLOBAL OPERATIONS · 全球业务</div><h1>你的下一步，在哪里</h1></div>${B('返回现场','scene','','ghost')}</div><div class="map-frame"><svg class="world-map" viewBox="${vb}" aria-label="华东智行业务世界地图" role="group"><g>${paths}</g><g>${Array.from({length:13},(_,i)=>`<path class="map-grid" d="M${i*30} 0V180M0 ${i*15}H360"/>`).join('')}</g>${routes}${businessLines()}<path class="map-route" d="M283.82 88.65L281.69 86.86"/><text class="map-country-label" x="278" y="54">中国</text><text class="map-country-label" x="312" y="72">太平洋</text>${nodes}</svg><div class="map-toggle">${B(mapWorld?'聚焦亚洲':'查看全球','zoommap','','ghost')}</div><div class="map-credit">亮线代表已落实的研发联动与业务合作 · 点击城市进入</div></div><details class="city-alternative"><summary>用城市列表选择地点</summary><div class="city-list">${Object.entries(C.cities).map(([id,c])=>`<button class="city-card ${id===S.city?'current':''}" data-a="city" data-id="${id}"><strong>${esc(c.name)} ${id===S.city?'· 当前':''}</strong><small>${esc(c.sub)}</small></button>`).join('')}</div></details></section><aside class="rail">${person('secretary')}<div class="quote">各地有不同的能力。跨城出差使用2次行动；日常委派与调查，可以先通过手机联系。</div><div class="rail-label">你正在${esc(C.cities[S.city].name)}</div>${placeButtons(S.city)?`<div class="stack">${Object.entries(C.places).filter(([id,p])=>p.city===S.city&&!['home','apartment','hq'].includes(id)).map(([id,p])=>B(p.name+' ›','placeInfo',id,'ghost full')).join('')}</div>`:''}<div class="rule"></div><div class="note">${S.phase==='night'?'现在是夜晚，可以浏览地图，但出发要等到明天。':'国内跨城1万元；跨境出差2万元。每次出差使用2次行动。'}</div><div class="rail-label">公司能力分布</div><p class="small">苏州负责战略、客户、法律、资金和人员；深圳与成都支撑硬件及算法。新加坡承接合作与港区交付，吉隆坡负责下一市场准备。日本是已有业务背景。</p></aside></div>`;}
function renderEndingLegacy(){if(S.ending.id==='bankrupt')return bankruptcyScreen();const e=S.ending;return `<div class="ending-layout"><div class="ending-visual"><img src="${asset(e.scene)}" alt="${esc(e.title)}结局场景"></div><section class="ending-card"><span class="achievement">${icon('briefcase')} 第${e.day}天 · 董事会复盘</span><h1>${esc(e.title)}</h1><p>${esc(e.summary)}</p><div class="metrics"><div class="metric"><strong>${e.cash}</strong><span>结清周转后的现金 / 万</span></div><div class="metric"><strong>${S.control}</strong><span>技术自主空间</span></div><div class="metric"><strong>${S.trust}</strong><span>合作信任</span></div></div>${e.evidence.map(x=>`<div class="evidence">${esc(x)}</div>`).join('')}<div class="rule"></div><p>${esc(e.future)}</p>${e.commercial?`<div class="note">${esc(e.commercial)}</div>`:''}${e.businessIncome!==undefined?businessSummary():''}<div class="toolbar" style="margin-top:22px">${B('看决策因果','company','','primary')}${B('同一开局再挑战','replay')}${B('新的商业局面','new')}</div></section></div>`;}
function renderLegacy(){if(!started)return startScreen();const mood=S.ending?(['setback','bankrupt'].includes(S.ending.id)?'loss':S.ending.id==='equity'?'mixed':'win'):S.events.some(e=>e.status==='open'&&['patentclaim','partnerbuyout','invoicefraud','formeremployer','accessrequest','vendorpressure','copy'].includes(e.id))?'crisis':S.phase==='night'?'night':S.place==='board'?'hope':S.place==='partner'?'negotiation':S.day>=10?'tension':'focus';sound.setMood(mood);sound.setScene(S.phase==='night'?(S.city==='suzhou'?'home':'apartment'):C.places[S.place]?.scene||'hq');$('#app').innerHTML=`<div class="shell">${header()}${S.ending?renderEnding():view==='map'?renderMap():renderScene()}</div>${controls()}`;setTimeout(refreshGuide,40);}
function startScreen(){let saved=null;try{saved=JSON.parse(localStorage.getItem(KEY)||'null');}catch{}$('#app').innerHTML=`<main class="start"><div class="start-visual"><img src="${asset('hq')}" alt="华东智行苏州总部的多层办公场景" fetchpriority="high"><div class="start-signature"><p>每一次开放，都有代价。</p><small>苏州 · 华东智行总部</small></div></div><section class="start-content"><div class="kicker">HUADONG INTELLILINK / CEO SIMULATION</div><h1>华东智行<br>出海决策室</h1><p class="intro">一份海外邀约，二十五天决策窗口。<br>带领你的团队，在订单、技术与信任之间，<br>走出属于华东的海外路线。</p><div class="start-facts"><div><strong>25</strong>个经营日</div><div><strong>6</strong>类结局</div><div><strong>5</strong>种现场互动</div></div>${saved?B('继续上次经营 '+icon('arrow'),'continue','','primary'):''}${B(saved?'开启新的商业局面':'进入苏州总部 '+icon('arrow'),'new','',saved?'ghost':'primary')}${B('了解经营方式','help','','ghost')}<div class="toolbar" style="margin-top:13px">${B('设置与存档','settings','','ghost')}${B('课程与来源','sources','','ghost')}</div><p class="source">面向知识产权策略学习的虚构企业模拟。<br>四份MIP503课件与作业贯穿不同经营路线。</p></section></main>`;}
function briefHTML(){return `<details class="brief"><summary>这次出海，要先知道什么？</summary><div class="detail-content"><p><b>我们有什么</b>：总部在苏州，深圳做设备研发，成都做算法。新智链可以帮忙联系当地客户、集成系统和处理项目事务。</p><p><b>这次可以花多少钱</b>：出海专项资金从80万元开始，共25天。白天有3次行动，阅读和咨询免费。一个部门最多同时接一项执行工作，再排一项。夜晚交易与审批分别计算。</p><p><b>钱怎么回来</b>：报价不等于收入。先把付款条件谈清楚，签约后满足条件才收到首付款；现场验收后才会有阶段款。还没到账的钱，不能拿来花。</p><p><b>现在最需要查清什么</b>：客户到底要什么，伙伴能派多少人，哪些技术可以开放。调查报告会带来新信息，也可能改变原来的判断。</p><p><b>如果现金吃紧</b>：可查看夜间融资和一次董事会追加申请，是否能得到资金取决于额度和本局材料。本轮项目资金耗尽会停止海外扩张，国内公司仍继续经营。</p><p><b>下一站怎么走</b>：首站完成交付后，再判断自己做、与伙伴做，还是通过许可和服务网络扩张。保住已完成的业务或主动止损，也是一种决定。</p></div></details>`;}
function ftoGraph(){const scope=S.flags.ftoScope||{},mods=scope.modules||[];const rows=[['通信网关',mods.includes('gateway'),['自有P-01 · 看维护与范围','SIM-A · 有效，同步步骤','SIM-D · 有效，认证握手'],'两项权利重叠影响本轮交付；分别处理后才能清除已查障碍。'],['预测维护',mods.includes('predict'),['代码／模型 · 权属与秘密','SIM-B · 届满记录','SIM-C · 已公开待审'],'届满记录与待审公开分别判断；不是整个产品的永久通行证。'],['连接与适配',false,['外包适配模块 · 许可链','伙伴连接器 · 引进授权'],'与FTO并列核查交易授权，查看权属与伙伴尽调报告。']];return `<div class="paper-heading">产品技术依赖图</div><div class="dependency-map">${rows.map(([name,covered,chips,note])=>`<article><div class="dependency-module">${name}<small>${covered?'本轮已列入调查':'另查授权或补充范围'}</small></div><span class="dependency-arrow">→</span><div><div class="toolbar">${chips.map(c=>`<span class="pill">${c}</span>`).join('')}</div><p class="small">${note}</p></div></article>`).join('')}</div><p class="source">权利编号为教学模拟。图示表现依赖与重叠，不按专利数量认定侵权。</p>`;}
function sourceTags(ids){return `<div class="source">相关知识：${ids.map(id=>{const t=C.topics.find(t=>t[0]===id);return t?`<button class="gold" data-a="topic" data-id="${id}">${esc(t[1])}</button>`:''}).join(' · ')}</div>`;}
function placeInfo(id){const p=C.places[id],avail=E.tasksAt(S,id);modal(p.name,`${person(p.person)}<p>${esc(p.desc)}</p><div class="rule"></div><p class="small">${esc(C.cities[p.city].name)} · ${p.city===S.city?'同城拜访':'需要先跨城出差'}</p><div class="note" style="margin-top:12px">${S.phase==='night'?'现在是夜间，明天才能实际前往。':avail.length?'这里有 '+avail.length+' 项当前可开展工作。进入后可先了解方案。':'这里目前没有与进度匹配的工作。实际前往将只收到问候，并使用1次行动和1万元执行费用。'}</div>${avail.map(t=>`<div class="report-line">${esc(t.title)}</div>`).join('')}<div class="toolbar dialog-footer">${B(S.phase==='night'?'明天再去':p.city===S.city?'实际前往':'安排前往'+C.cities[p.city].name,p.city===S.city?'visit':'travelAsk',p.city===S.city?id:p.city,'primary',S.phase==='night'?'disabled':'')}${B('先不前往','close','','ghost')}</div>`,{kicker:'地点信息 · 浏览不耗时'});}
function cityInfo(id){const c=C.cities[id];modal(c.name+' · '+c.sub,`<img style="width:100%;border-radius:4px;margin-bottom:17px" src="${asset(c.scene)}" alt="${esc(c.name)}的业务场景">${c.context?'<div class="note">华东在日本已有业务。它是本轮经营的背景；这次可操作的出海项目集中在新加坡与马来西亚。</div>':`<p class="small">${id===S.city?'你已在这里。查看地点后决定是否实际拜访。':'远程沟通不要求本人在当地，现场会谈与验收需要出差。'}</p><div class="stack" style="margin-top:16px">${Object.entries(C.places).filter(([k,p])=>p.city===id&&!['home','apartment'].includes(k)).map(([k,p])=>B(p.name+' ›','placeInfo',k,'ghost full')).join('')}</div>${id!==S.city?B('安排出差 · 2次行动','travelAsk',id,'primary full','style="margin-top:20px"'):''}`}`,{kicker:'世界地图 · 地点详情'});}
function taskModalLegacy(id,remote=false,preserve=false){const t=C.taskById[id];activeTask=id;remoteTask=remote;if(!preserve)draft=t.type==='license'?S.license.slice():[];const avail=E.available(S,t),nightOK=S.phase==='day'||remote&&t.night&&!S.nightUsed;const prefix=`${person(t.person)}<p>${esc(t.brief)}</p><div class="source">${remote?'手机委派':'现场决策'} · ${t.type==='finish'?'提交结果':S.phase==='night'?'今晚一次主要审批':'使用1次行动'} · 阅读本页不耗时</div>`;if(!avail){modal(t.title,prefix+`<div class="note" style="margin-top:16px">${esc(E.reason(S,t))}</div>`);return;}
let body=prefix;if(!nightOK)body+='<div class="note danger" style="margin-top:15px">今晚可以了解方案；常规审批需要等到明天。</div>';
if(t.intro)body+=`${briefHTML()}<div id="meeting-panel">${debatePanel('strategy')}</div><div class="note" style="margin:16px 0">许知微整理：先统一增长方向，再分配调查、人手和交付资源。本次战略安排2万元，后续工作分别核对费用。</div>`;
if(t.type==='assets'){body+=`<div class="note" style="margin-top:16px">选择顺序即优先级。选满五项后，可以上移或移除。审计会重点核对这五项。</div><div id="asset-list">${assetChecklist()}</div>`;}
else if(t.type==='license'){body+=`<div id="meeting-panel">${debatePanel('license')}</div><div class="note" style="margin-top:16px">当前架构：${({hybrid:'混合部署，需要运行版与接口',local:'完整本地部署，需要运行版',cloud:'云端部署，需要接口'})[S.flags.product]||'先完成产品验证'}。开放适配、核心或权重可增加伙伴能力，也改变控制与报价。</div>${C.licenseAssets.map(([id,name,kind,note])=>`<label class="choice-check"><input type="checkbox" name="license" value="${id}" ${draft.includes(id)?'checked':''}><span class="grow"><strong>${esc(name)} <span class="pill">${esc(kind)}</span></strong><small>${esc(note)}</small>${id==='patent'&&!S.flags.patentReady?'<small class="danger">自有权利状态尚未核实</small>':id==='adapt'&&!S.flags.rights?'<small class="danger">适配许可链仍需处理</small>':''}</span></label>${['core','weights'].includes(id)?`<label class="field license-mode" data-mode-for="${id}"><span>${esc(name)} · 特别开放条件</span><select name="mode-${id}"><option value="controlled" ${S.licenseModes?.[id]!=='copy'?'selected':''}>受控协作 · 不交付完整副本</option><option value="copy" ${S.licenseModes?.[id]==='copy'?'selected':''}>限定交付副本 · 提高伙伴自主排障</option></select><small>只在勾选该项时生效。受控协作减少暴露，但伙伴可承担的人手和报价增幅较少；实际权限仍要部署。</small></label>`:''}`).join('')}<div class="selection-summary"><div id="license-summary" class="small"></div>${B('确认本轮许可清单','submitTask',id,'primary full',!nightOK?'disabled':'')}</div>`;}
else if(t.type==='fto'){body+=`<form id="task-form"><div class="form-grid"><fieldset><legend>相关市场</legend><label class="choice-check"><input type="checkbox" name="country" value="sg" checked><span>新加坡 · 首期部署</span></label><label class="choice-check"><input type="checkbox" name="country" value="my"><span>马来西亚 · 下一站</span></label></fieldset><fieldset><legend>产品模块</legend><label class="choice-check"><input type="checkbox" name="module" value="gateway" checked><span>通信网关与同步步骤</span></label><label class="choice-check"><input type="checkbox" name="module" value="predict" checked><span>预测维护与接口</span></label></fieldset></div><label class="field"><span>分析深度</span><select name="depth"><option value="quick">快速初筛 · 2万元 / 1天</option><option value="focused" selected>重点比对产品涉及的专利 · 5万元 / 1天</option><option value="full">扩大比对范围并设跟踪 · 8万元 / 2天</option></select></label><div class="note">增加马来西亚调查另需2万元。部门排队可能推迟报告；任何结论均仅限已分析的范围与时间。</div><div id="fto-cost" class="source"></div>${B('提交调查委托','submitTask',id,'primary full','style="margin-top:18px" '+(!nightOK?'disabled':''))}</form>`;}
else if(t.type==='terms'){const v=S.terms||{territory:'project',exclusive:'none',improvements:'split',sub:'named',exit:'managed'};const fields=[['territory','地域与用途',[['project','新加坡列名项目 / 2年'],['regional','东盟列名行业 / 3年']]],['exclusive','市场独占',[['none','非独占 · 自由拓客，伙伴人手少'],['performance','有限独占 · 有业绩与退出节点'],['open','区域独占 · 无清晰业绩退出']]],['improvements','新产生的技术成果',[['split','区分原有与新成果，约定互惠使用'],['shared','共同成果共同使用、核对贡献'],['partner','本地改进由伙伴控制']]],['sub','分包与再许可',[['named','限定列名对象，范围变化另审'],['free','允许伙伴自行增加对象']]],['exit','结束后的技术与服务',[['managed','撤销访问、返还资料、衔接服务'],['later','合作结束时再协商']]]];body+=`<form id="task-form"><div class="terms-grid">${fields.map(([n,label,opts])=>`<label class="field"><span>${label}</span><select name="${n}">${opts.map(([x,txt])=>`<option value="${x}" ${v[n]===x?'selected':''}>${txt}</option>`).join('')}</select></label>`).join('')}</div><div class="note">第${S.rounds+1}轮 / 最多3轮。新智链会把条件换算成人手、首付款和服务费，再给出还价。尚未签约就没有收入。</div>${B('提出条件，等待还价','submitTask',id,'primary full','style="margin-top:18px" '+(!nightOK?'disabled':''))}</form>`;}
else{body+=`<div style="margin-top:18px">${t.options.map(o=>{const cost=t.type==='finish'?0:Math.max(1,o.cost+(id==='strategy'?20:0));const timing=P.plan(S,{type:'task',id,payload:{option:o.id}});const disabled=!nightOK||(o.requireFlag&&!S.flags[o.requireFlag])||timing?.blocked||cost>S.cash;const ahead=S.jobs.filter(j=>j.dept===(o.dept||t.person)&&['running','queued'].includes(j.status)),due=o.duration?(ahead.length?Math.max(...ahead.map(j=>j.due)):S.day)+o.duration:null;return `<button class="choice" data-a="option" data-id="${id}" data-option="${o.id}" ${disabled?'disabled':''}><strong>${esc(o.label)}</strong><p>${esc(C.language.thought(t,o).good)}</p><div class="cost"><span>${cost?cost+'万元':'无前置费用'}</span><span>${due?'第'+due+'天交报告'+(ahead.length?' · 已计部门排队':''):t.type==='finish'?'结清周转，形成结局':'决定后执行'}</span>${cost>S.cash?'<span>当前现金不足</span>':''}${o.requireFlag&&!S.flags[o.requireFlag]?'<span>前提尚未满足</span>':''}${timing?.blocked?'<span>赶不上第25天，请换短方案或撤回排队工作</span>':timing?.warn?'<span>秘书提醒：这个排期比较紧</span>':''}</div></button>`;}).join('')}</div>`;}
body+='<details><summary>专业名称与详细依据</summary><p class="small">'+esc(t.formalTitle||t.title)+'</p>'+sourceTags(t.topics)+'</details>';modal(t.title,body,{wide:t.intro||t.type==='license',kind:'task',kicker:(remote?'手机 · 委派工作':'负责人会谈')+' / '+C.people[t.person].role});if(t.type==='license')updateLicense();if(t.type==='fto')updateFto();if(t.type==='terms')updateTerms();}
function assetChecklist(){return C.assets.map(a=>`<label class="choice-check"><input type="checkbox" name="asset" value="${a.id}" ${draft.includes(a.id)?'checked':''}><span class="grow"><strong>${esc(a.name)} <small>${esc(a.kind)}</small></strong><small>${esc(a.need)}</small></span></label>`).join('')+`<div class="selection-summary"><div class="row spread"><b>优先级 ${draft.length} / 5</b><small>上方先审</small></div><ol class="ordered">${draft.map((id,i)=>`<li><span>${i+1}</span><span class="grow">${esc(C.assets.find(a=>a.id===id).name)}</span><button class="icon-btn" data-a="assetUp" data-id="${id}" aria-label="上移${esc(C.assets.find(a=>a.id===id).name)}" ${i===0?'disabled':''}>↑</button><button class="icon-btn" data-a="assetRemove" data-id="${id}" aria-label="移除${esc(C.assets.find(a=>a.id===id).name)}">×</button></li>`).join('')}</ol>${B('确认五项资产与顺序','submitTask','assets','primary full',draft.length!==5||S.phase==='night'?'disabled':'')}</div>`;}
function updateLicense(){const a=[...dialog.querySelectorAll('input[name=license]:checked')].map(i=>i.value);dialog.querySelectorAll('[data-mode-for]').forEach(el=>el.hidden=!a.includes(el.dataset.modeFor));$('#license-summary').textContent=`本轮选择 ${a.length} 项：${a.map(id=>C.licenseAssets.find(x=>x[0]===id)?.[1]||id).join("、")}。${a.includes('core')||a.includes('weights')?'包含核心技术资料，交付控制需相应加强。':'可以用接口与适配能力支持合作。'}`;const copies=['core','weights'].some(id=>a.includes(id)&&dialog.querySelector('[name=mode-'+id+']')?.value==='copy');formThought(a.includes('core')||a.includes('weights')?'让对方接触更多技术，排障和投入可能更积极。':'先用接口和适配支持合作，核心更容易留在自己手里。',copies?'完整副本交出去以后很难收回，承诺保密之外还得管下载和再分享。':'合作范围收得紧，对方能独立承担的工作可能少一些；访问权限仍要实际部署。');}
function formThoughtLegacy(good,bad){let el=$('#form-thought');if(!el){el=document.createElement('section');el.id='form-thought';el.className='ceo-thought';const before=dialog.querySelector('[data-a="submitTask"]');if(before)before.before(el);}el.innerHTML=`<div class="thought-heading">CEO · 我心里盘算着</div><div class="thought-pro"><span>能得到</span><p>“${esc(good)}”</p></div><div class="thought-con"><span>得想想</span><p>“${esc(bad)}”</p></div>`;}
function updateFto(){const f=$('#task-form'),depth=f.elements.depth.value,countries=[...f.querySelectorAll('[name=country]:checked')].map(i=>i.value),modules=[...f.querySelectorAll('[name=module]:checked')].map(i=>i.value),p=P.plan(S,{type:'task',id:'fto',payload:{depth,countries,modules}});const good=depth==='quick'?'先低成本看看大概情况，能早点发现明显问题。':depth==='focused'?'把这次产品真正会用到的专利范围重点对一遍。':'把范围查得更全一点，也安排后续跟踪。';const bad=depth==='quick'?'这只是初筛，不能拿它当成产品已经安全。':depth==='focused'?'查过的国家和模块才有依据，版本变了还得重看。':'花钱更多，还需要两天；报告到手以后可能仍要整改。';formThought(good,bad+(!countries.includes('sg')||modules.length<2?'这次勾选还有缺口，别把没查的当没问题。':''));$('#fto-cost').innerHTML='本次 '+p.cost+'万元 · 第'+p.start+'天开始 → 第'+p.due+'天完成'+(p.queued?'（已计排队）':'')+(p.message?'<p class="small danger">许知微：'+esc(p.message)+'</p>'+B('查看部门排期','company','jobs','ghost'):'');dialog.querySelector('[data-a="submitTask"]').disabled=p.blocked||(S.phase==='night'&&(!C.taskById.fto.night||S.nightUsed));}
function updateTerms(){const f=$('#task-form');if(!f)return;const exclusive=f.elements.exclusive.value,improvements=f.elements.improvements.value,exit=f.elements.exit.value;formThought(exclusive==='none'?'我还能自己找客户，市场选择更自由。':'给对方一定地盘，换它更愿意投入人手。',(exclusive==='open'?'没写业绩和退出条件，以后想换人可能很难。':'独占的范围、期限和兑现条件得盯住。')+(improvements==='partner'?'本地新成果更多归对方掌握。':'新成果谁能用，要留下贡献记录。')+(exit==='later'?'散伙时再谈资料和客户怎么交接，容易被动。':''));}

function submitTask(id,option){const t=C.taskById[id];let payload;if(option)payload={option};else if(t.type==='assets')payload={ids:draft.slice()};else if(t.type==='license'){payload={ids:[...dialog.querySelectorAll('input[name=license]:checked')].map(i=>i.value),modes:{}};for(const id of ['core','weights'])if(payload.ids.includes(id))payload.modes[id]=dialog.querySelector('[name=mode-'+id+']').value;}else if(t.type==='fto')payload={countries:[...dialog.querySelectorAll('input[name=country]:checked')].map(i=>i.value),modules:[...dialog.querySelectorAll('input[name=module]:checked')].map(i=>i.value),depth:$('#task-form').elements.depth.value};else if(t.type==='terms'){payload={};for(const k of ['territory','exclusive','improvements','sub','exit'])payload[k]=$('#task-form').elements[k].value;}const action={type:'task',id,payload,remote:remoteTask};if(timingGuard(action))return;let next;try{next=E.dispatch(S,action);}catch(e){$('#modal-error').textContent=e.message;return;}const last=next.log.slice(S.log.length).find(x=>x.title===t.title)||{text:'本次方案已核对，确认后执行。'},job=next.jobs.length>S.jobs.length?next.jobs.at(-1):null;pending=action;if(!['license','negotiate'].includes(id)){run(action);return;}const surprise=['acceptance','review','negotiate'].includes(id);const preview=surprise?(id==='negotiate'?'把技术范围、独占安排和新成果条款送到谈判桌，等待伙伴还价。执行费用1万元。':id==='acceptance'?'提交当前证据和范围，由客户决定是否接受并付款。已知缺口可在经营准备图中查看。':'提交已发生的合同、交付与资金结果，等待董事会评估。'):last.text;modal('确认这项安排',`${person(t.person,'等待你的决定','small')}<h3>${esc(t.title)}</h3><p style="margin-top:12px">${esc(preview)}</p><div class="metrics"><div class="metric"><strong>${surprise?'待结果':Math.round((next.cash-S.cash)*10)/10}</strong><span>${surprise?'实际结算':'立即现金变化 / 万'}</span></div><div class="metric"><strong>${t.type==='finish'?'结算':S.phase==='night'?'1项':'1次'}</strong><span>${S.phase==='night'?'夜间审批':'使用的日程'}</span></div><div class="metric"><strong>${surprise?'待评估':job?'D'+job.due:next.cash}</strong><span>${surprise?'提交后揭晓':job?'报告预计送达':'安排后现金 / 万'}</span></div></div>${job?`<div class="note">${C.people[job.dept]?.role||'团队'}${job.status==='queued'?'已有工作，按顺序执行。':'开始执行。'}报告完成后，仍需阅读并决定如何处理缺项。</div>`:''}<div class="toolbar dialog-footer">${B('确认执行','execute','','primary')}${B('返回调整','taskBack','','ghost')}</div>`,{kicker:'只有确认执行才推进时间',kind:'confirm'});}
function offer(){if(S.completed.contract){docs('contract');return;}const o=S.offer;if(!o){toast('尚未收到还价。');return;}modal('新智链的还价',`${person('partner')}<div class="quote">${esc(o.text)}</div><div class="metrics"><div class="metric"><strong>${o.value}</strong><span>合同总额 / 万</span></div><div class="metric"><strong>${o.deposit}</strong><span>签约后首付款 / 万</span></div><div class="metric"><strong>${o.staff}</strong><span>伙伴承诺的人力份额</span></div></div><table class="money-table"><tbody><tr><td>正式合作治理投入</td><td>${o.governanceCost} 万</td></tr><tr><td>阶段交付时伙伴服务费</td><td>${o.partnerFee} 万</td></tr><tr><td>华东补足支持投入</td><td>${o.support} 万</td></tr><tr><td>制造与交付基础费用</td><td>24 万</td></tr></tbody></table><div class="note" style="margin-top:16px">首付款只有签约后到账。阶段验收款占合同40%，剩余为附条件尾款。许可对象与条件已保存，可以在手机里的“合同与课程”中核对。</div><div class="toolbar dialog-footer">${B('接受还价并正式签约','signAsk','','primary',S.completed.contract?'disabled':'')}${S.rounds<3?B('调整合作条件','task','negotiate','ghost'):''}${S.rounds<3?B('重审技术清单','task','license','ghost'):''}</div><p class="source">正式签约需要本人白天在新加坡新智链会议室。最多3轮报价，不要求所有条件都选最保守。现场核对伙伴排班，有机会争取额外人手。</p>`,{kind:'offer',kicker:'谈判第'+o.round+'轮 · 报价尚未成为收入'});}
function reportLegacy(id){if(!S.reports[id])return;run({type:'readReport',id},false);const r=S.reports[id],v=I.report(S,r);if(id==='inspection'&&S.flags.component){v.rows=v.rows.map(x=>x.detail?.includes('组件')?{...x,status:'done',label:'这个问题已经补齐',detail:'第'+(S.reports.component?.day||S.day)+'天已核对最终软件。此处保留原检查记录，当前状态以新报告为准。'}:x);if(!E.risks(S).length)v.headline='先前发现的关键缺口已处理';}sound.effect('paper');const next=[...new Set(v.next)].filter(id=>C.taskById[id]&&E.available(S,C.taskById[id])).slice(0,2);modal(r.title,`<div class="report-date">第${r.day}天送达 · 先看结论，再看依据</div><h3 class="report-conclusion">${esc(v.headline)}</h3><div class="evidence-steps">${v.steps.map((x,i)=>`<span><b>${i+1}</b>${x}</span>`).join('')}</div>${v.range?`<div class="value-range"><strong>${v.range.min}—${v.range.max}<small>万元</small></strong><div class="range-line"></div><span>${v.range.label} · 非保证成交价</span></div>`:''}<div class="report-cards">${v.rows.map(x=>`<article class="report-cell ${x.status}"><span class="signal">${x.status==='done'?icon('check'):x.status==='attention'?icon('shield'):icon('folder')}</span><div><h3>${esc(x.label)}</h3><p>${esc(x.detail)}</p></div></article>`).join('')}</div>${id==='fto'?`<details><summary>展开产品与技术依赖图</summary>${ftoGraph()}</details>`:''}${next.length?`<div class="paper-heading">接下来可以做</div><div class="stack">${next.map(id=>suggestionRow({task:id,label:C.taskById[id].title})).join('')}</div>`:`<div class="note">已归档。${S.jobs.some(j=>['queued','running'].includes(j.status))?'团队仍在推进其他工作，可从手机查看排期。':'让许知微结合当前进度推荐下一步。'}</div>`}<details class="report-details"><summary>详细依据与范围（${r.lines.length}条）</summary>${r.lines.map(l=>`<p class="report-line">${esc(l)}</p>`).join('')}${sourceTags(r.topics)}</details><div class="toolbar dialog-footer">${B('读完，回到现场','close','','primary')}${B('查看其他报告','phone','reports','ghost')}</div>`,{kind:'report',kicker:'图解报告 · 阅读不消耗行动'});}
function eventView(id){openLetter(id);}
function phoneLegacy(tab='oa'){if(tab==='jobs'){company('jobs');return;}if(tab==='contacts')tab='team';const tasks=C.tasks.filter(t=>t.remote&&E.available(S,t)),canTonight=t=>S.phase==='day'||t.night&&!S.nightUsed;let body='';
if(tab==='team')body=Object.entries(C.people).sort(([a],[b])=>Number(b==='secretary')-Number(a==='secretary')+Number(C.tasks.some(t=>t.person===b&&taskStatus(t).ready))-Number(C.tasks.some(t=>t.person===a&&taskStatus(t).ready))).map(([id,p])=>{const ts=C.tasks.filter(t=>t.person===id),ready=ts.filter(t=>taskStatus(t).ready),jobs=S.jobs.filter(j=>j.dept===id&&['queued','running'].includes(j.status));return `<section class="team-section"><div class="team-heading">${portrait(id,'small')}<div class="grow"><b>${esc(p.name)}</b><small>${esc(p.role)}</small></div><span class="team-status ${ready.length?'ready':'muted'}">${ready.length?ready.length+'项可安排':id==='secretary'?'随时可问':jobs.length?'工作进行中':'暂无可安排工作'}</span></div>${id==='secretary'?B('请秘书理清下一步','secretary','','ghost full'):ready.slice(0,2).map(t=>contactTaskRow(t)).join('')+(ready.length?B('全部职责与排期','contact',id,'ghost full'):ts.slice(0,2).map(t=>contactTaskRow(t)).join('')+B('查看其他职责','contact',id,'ghost full'))}</section>`;}).join('');
else if(tab==='reports'){const reports=Object.values(S.reports).sort((a,b)=>Number(a.read)-Number(b.read)||b.day-a.day);body=`${reports.length?reports.map(r=>`<button class="task-row" data-a="report" data-id="${r.id}" ${!r.read&&S.phase==='day'?'disabled':''}>${icon('folder')}<div class="grow"><strong>${esc(r.title)}</strong><small>第${r.day}天 · ${r.read?'已归档':'新报告，免费阅读'}</small></div>${r.read?'›':'<span class="badge">新</span>'}</button>`).join(''):`<div class="empty-state">${icon('folder')}<h3>暂时没有报告</h3><p>完成调查或研发委派后，报告会按排期送达。</p>${S.jobs.some(j=>['queued','running'].includes(j.status))?jobsHTML():B('请许知微推荐下一步','secretary','','primary')}</div>`}<details><summary>合作档案与课程</summary><div class="stack">${B('合作目标、技术与合同','contractArchive','','ghost')}${B('课程知识图谱','topicArchive','','ghost')}</div></details>`;}
else{const urgent=S.events.filter(e=>['open','report','investigating','settling','working'].includes(e.status));const suggested=new Set(E.goal(S).ids);if(guide?.task)suggested.add(guide.task);const available=tasks.filter(canTonight),first=available.filter(t=>suggested.has(t.id)),rest=available.filter(t=>!suggested.has(t.id));body=`<div class="rail-label">优先处理 <span>${urgent.filter(e=>['open','report'].includes(e.status)).length}项</span></div>${urgent.map(e=>`<button class="task-row urgent-row" data-a="event" data-id="${e.id}">${icon('mail')}<div class="grow"><strong>${esc(C.eventById[e.id].title)}</strong><small>${e.status==='settling'?'履约中 · 第'+e.payDay+'天核对到账':e.status==='working'?'团队作业中 · 第'+e.workDay+'天完成':e.status==='investigating'?'已委派，等待调查':'第'+e.due+'天前回应'} · ${e.status==='report'?'新调查结果':'事务来信'}</small></div>›</button>`).join('')||'<p class="small">当前没有紧急事项，可以按计划推进。</p>'}${Object.values(S.reports).some(r=>!r.read)?B('有'+Object.values(S.reports).filter(r=>!r.read).length+'份新报告，去图解阅读','phone','reports','ghost full','style="margin-top:14px"'):''}<div class="rail-label">${S.phase==='night'?'今晚可办':'当前任务的远程工作'}</div>${first.map((t,i)=>taskRow(t,i,true)).join('')||`<p class="small">${S.phase==='night'?(S.nightUsed?'今晚的审批已完成，其他工作明天继续。':'常规委派明天继续；今晚可处理上方紧急来信。'):'当前关键步骤需要到现场，许知微可以为你指路。'}</p>`}${rest.length?`<details><summary>${S.phase==='night'?'其他夜间支持':'其他可委派工作'}（${rest.length}项）</summary>${rest.map((t,i)=>taskRow(t,i,true)).join('')}</details>`:''}${S.jobs.some(j=>['queued','running'].includes(j.status))?`<details ${!first.length?'open':''}><summary>部门进度与排期</summary>${jobsHTML()}</details>`:''}${S.phase==='night'&&tasks.some(t=>!canTonight(t))?`<details><summary>明日可委派（${tasks.filter(t=>!canTonight(t)).length}项）</summary><p class="small">今晚仅预览，明天从待办中选择。</p>${tasks.filter(t=>!canTonight(t)).map(t=>`<div class="compact-duty"><b>${esc(t.title)}</b><small>${esc(C.people[t.person].role)} · 明天使用1次行动</small></div>`).join('')}</details>`:''}${!tasks.length&&!urgent.length?waitingCard():''}`;}
modal('公司手机',`<div class="phone-inset"><div class="tabs">${[['oa','待办'],['team','联系人'],['reports','报告']].map(([id,l])=>`<button class="${id===tab?'active':''}" data-a="phone" data-id="${id}">${l}</button>`).join('')}</div>${body}</div>`,{kind:'phone',kicker:S.phase==='night'?'夜间 · 来信优先，其余明天办':'白天 · 远程委派使用1次行动'});}
function jobsHTML(){const jobs=S.jobs.filter(j=>['running','queued'].includes(j.status));return `<p class="small">同部门按顺序开工，不同部门可以同时推进。灰色已开工项目不能撤回。</p>${jobs.length?jobs.map(j=>`<div class="report-line"><span class="pill ${j.due>25?'danger':''}">${j.status==='queued'?'排队中':'执行中'}</span><h3>${esc(C.taskById[j.task]?.title||C.eventById[j.data?.event||j.data?.business||j.data?.drama]?.title||'事件调查')}</h3><small>${esc(C.people[j.dept]?.role||'团队')} · D${j.start} 开始 → D${j.due} 夜晚汇报 ${j.due>25?'· 超过结局，请优先调整':''}</small><div class="bar"><i style="width:${Math.max(0,Math.min(100,(S.day-j.start)/Math.max(1,j.due-j.start)*100))}%"></i></div>${B(j.status==='queued'?'撤回这项，让后面的工作提前':'已经开工，等待结果','cancelJobAsk',j.id,'ghost',j.status==='queued'?'':'disabled')}</div>`).join(''):'<p class="empty">目前没有排队或执行中的工作。</p>'}${B('去联系人安排工作','phone','team','primary full')}`;}

function taskStatus(t){const job=S.jobs.find(j=>j.task===t.id&&['running','queued'].includes(j.status));let reason='';if(job)reason='已安排 · 第'+job.due+'天夜晚交报告';else if(!E.available(S,t))reason=E.reason(S,t)||'当前阶段还不能做';else if(!t.remote)reason='需要到'+C.places[t.place].name+'当面决定';else if(S.phase==='night'&&(!t.night||S.nightUsed))reason=S.nightUsed?'今晚的审批已用完，明天再办':'白天可安排，今晚先休息';const plans=P.options(S,t).map(x=>x.plan).filter(Boolean);if(!reason&&plans.length&&plans.every(x=>x.blocked))reason='排期已超过第25天，先撤回不急的工作';if(!reason&&plans.length&&plans.every(x=>x.cost>S.cash))reason='当前现金不足，先联系财务';return {ready:!reason,reason,plans};}
function contactTaskRow(t){const st=taskStatus(t),valid=st.plans.filter(x=>!x.blocked),days=valid.map(x=>x.due),due=days.length?Math.min(...days):null;return `<div class="contact-task ${st.ready?'available':'unavailable'}"><button class="task-row" data-a="task" data-id="${t.id}" data-remote="1" ${st.ready?'':'disabled'}><div class="grow"><strong>${esc(t.title)}</strong><small>${st.ready?(due>S.day?'最快第'+due+'天完成 · 先看方案':'现在可决定 · 先看方案'):esc(st.reason)}</small></div>${st.ready?'<span class="arrow">›</span>':''}</button>${!t.remote&&E.available(S,t)?followButton({task:t.id},'秘书带我去现场','text-action'):''}</div>`;}
function timingGuard(action){const p=P.plan(S,action);if(!p||(!p.warn&&!p.blocked))return false;timingDraft=action;modal(p.blocked?'这项排期赶不上结局':'许知微提醒：给后续留一点时间',`${person('secretary')}<div class="quote">${esc(p.message)}</div><div class="timeline-summary"><span>现在<br><b>D${S.day}</b></span><i>→</i><span>开始<br><b>D${p.start}</b></span><i>→</i><span class="${p.blocked?'danger':''}">完成<br><b>D${p.due}</b></span><i>／</i><span>结局<br><b>D25</b></span></div><p class="small">${esc(p.label)} · ${esc(C.people[p.dept]?.role||'团队')}。目前还没有扣款，也没有消耗行动。</p><div class="toolbar">${p.blocked?'':B('我接受这个排期，确认执行','timingProceed','','primary')}${B('先调整部门排期','company','jobs','ghost')}${B('暂不安排','close','','ghost')}</div>`,{kind:'timing',kicker:'秘书排期检查 · 安排前提醒'});return true;}
function chooseDecisionLegacy(el,selected=false){if(el.disabled||!S)return;const type=el.dataset.a==='option'?'task':'event',id=el.dataset.id,option=el.dataset.option;let o,t,thought;if(type==='task'){t=C.taskById[id];o=t.options.find(x=>x.id===option);thought=C.language.thought(t,o);}else{t=C.eventById[id];const e=S.events.find(x=>x.id===id);o=E.eventOptions(S,e)?.find(x=>x.id===option);thought=o?.thought||C.language.eventThoughts[id+'.'+option];const base={investigate:['先查清发生了什么，再决定要不要花大钱。','报告要等，而且查出来的问题还得另花时间解决。'],contain:['先把眼前影响压住，给团队留出调查时间。','先花的这笔钱不一定解决根本问题，仍要追后续。'],ignore:['今天把人和钱留给主项目。','这封来信不会因为我不理就消失，可能错过机会或留下麻烦。'],fix:['按查到的事实补问题，后面更容易交付。','现在要用掉预算和一次行动，别的事只能往后放。'],reduce:['先做自己能兑现的部分，减少继续出问题的机会。','范围缩小以后，这笔生意也可能变小。'],leave:['暂时不追加投入，手上还能留些余地。','未解决的事项会继续影响合作，不能当它已经好了。']};if(!thought){const pair=base[option]||[o?.desc||'这条路能推进眼前的事情。','还得看团队能否按时做完，承诺不能超出手里的能力。'];thought={good:pair[0],bad:pair[1]};}}
 if(!o&&type==='task')return;choiceDraft={type,id,option};dialog.querySelectorAll('.choice[data-option]').forEach(b=>{const on=b===el;b.classList.toggle('considering',on);b.setAttribute('aria-pressed',String(on));});let box=$('#ceo-thought');if(!box){box=document.createElement('section');box.id='ceo-thought';box.className='ceo-thought';box.setAttribute('aria-live','polite');const options=el.closest('.letter-options')||el.parentElement;options.after(box);}const action=type==='task'?{type,id,payload:{option}}:{type,id,option},p=P.plan(S,action);box.innerHTML=`<div class="thought-heading"><span>CEO · 我心里盘算着</span><small>${selected?'点选只预览，确认才执行':'移到另一项，可以换个角度想'}</small></div><b>${esc(o?.label||el.querySelector('strong')?.textContent)}</b><div class="thought-pro"><span>能得到</span><p>“${esc(thought.good)}”</p></div><div class="thought-con"><span>得想想</span><p>“${esc(thought.bad)}”</p></div>${p?.duration?`<div class="thought-date">${esc(C.people[p.dept]?.role||'团队')} · D${p.start}开始 → D${p.due}夜晚汇报${p.queued?' · 已计入排队':''}</div>`:''}${p?.message?`<p class="small ${p.blocked?'danger':''}">许知微：${esc(p.message)}</p>`:''}${B(p?.blocked?'这个排期赶不上，请先调整':'决定了，就按这一项办','choiceCommit','','primary full',p?.blocked?'disabled':'')}${p?.blocked?B('查看排期','company','jobs','ghost full'):''}`;if(selected){sound.effect('paper');box.scrollIntoView({block:'nearest',behavior:'smooth'});}}
function showWork(old,a){const newJobs=S.jobs.filter(j=>!old.jobs.some(x=>x.id===j.id));if(!newJobs.length){maybePriority();return;}const j=newJobs[0],dept=j.dept,t=C.taskById[a.id]||C.eventById[a.id],scene=({legal:'legal',finance:'finance',market:'market',hardware:'shenzhen',algorithm:'chengdu',hr:'hr',partner:'partner'})[dept]||'board',stages=({legal:['收到委派，打开本次资料','对照授权、日期和产品范围','圈出疑点，整理需要追问的证据'],finance:['收到安排，核对款项清单','逐笔对照账户、合同和凭证','列出缺项，准备联系相关负责人'],hardware:['收到任务，打开实验台','设备接入，开始采集测试数据','记录异常，准备下一轮验证'],algorithm:['收到任务，载入测试样本','逐项比对输出和访问记录','记录差异，整理修正方案'],market:['收到安排，整理客户名单','联系客户，核实需求与承诺','汇总反馈，准备后续沟通'],hr:['收到安排，核对人员与职责','逐一联系，确认交接与备份','整理名单，安排后续落实']})[dept]||['收到你的安排','团队开始分工处理','整理资料，按排期跟进'];if(j.status==='queued')stages.splice(0,3,'收到委派，检查需要的材料','预留工作时段，等待前项完成','准备就绪，第'+j.start+'天正式开工');clearTimeout(workTimer);const legal=dept==='legal';modal(C.people[dept]?.role+' · '+(j.status==='queued'?'收到任务，等待开工':'开始执行'),`<div class="work-cinema ${legal?'legal-cinema':''}"><div class="work-picture" style="${legal?'background-image:url('+asset('legal-work')+')':'background-image:url('+asset(scene)+')'}"></div><div class="work-scan" aria-hidden="true"></div><div class="work-caption"><span class="live-dot"></span><b id="work-stage">${esc(stages[0])}</b></div></div><div class="work-steps">${stages.map((s,i)=>'<span class="'+(!i?'active':'')+'">'+(i+1)+'. '+esc(s)+'</span>').join('')}</div><p class="small">${esc(t?.title||'这项工作')} · ${j.status==='queued'?'前一项工作完成后，第'+j.start+'天正式开工':'团队正在推进'}。预计第${j.due}天送达结果，动画不代表调查已经完成。</p>${B('收到，继续我的工作','workNext','','primary full')}`,{wide:true,kind:'work',kicker:'部门现场 · 按实际排期交付'});let n=0;function step(){if(modalKind!=='work')return;n++;if(n<3){$('#work-stage').textContent=stages[n];dialog.querySelectorAll('.work-steps span').forEach((x,i)=>x.classList.toggle('active',i===n));sound.effect(n===1?'paper':'confirm');workTimer=setTimeout(step,1800);}}workTimer=setTimeout(step,1800);sound.effect('paper');}

function contactLegacy(id){if(id==='secretary'){secretary();return;}const p=C.people[id],all=C.tasks.filter(t=>t.person===id),messages=S.messages.filter(m=>m.person===id).slice(-5);const ordered=all.slice().sort((a,b)=>Number(taskStatus(b).ready)-Number(taskStatus(a).ready));modal(p.name+' · '+p.role,`${person(id)}<p class="small">先选工作，再看方案。灰色项目会说明为什么现在不能办。</p><div class="contact-jobs">${ordered.map(t=>contactTaskRow(t)).join('')||'<p class="small">这位联系人通过来信、现场会谈参与项目。</p>'}</div>${S.events.filter(e=>C.eventById[e.id].person===id&&['open','report','working','settling','investigating'].includes(e.status)).map(e=>B(C.eventById[e.id].title,'event',e.id,'ghost full')).join('')}<details><summary>之前的消息（${messages.length}条）</summary>${messages.map(m=>`<div class="message"><small>第${m.day}天 · ${esc(m.title)}</small>${esc(m.text)}${m.kind==='report'?B('阅读报告','report',m.ref,'ghost'):m.kind==='event'?B('查看来信','event',m.ref,'ghost'):''}</div>`).join('')}</details><div class="toolbar">${B('返回联系人','phone','team','ghost')}${B('查看所有部门排期','company','jobs','ghost')}</div>`,{kind:'contact',kicker:'直接安排工作 · 阅读不消耗行动'});}

function secretaryOld(){const h=E.secretary(S,2),t=h.targets[0];modal('许知微 · 我来帮你理清下一步',`${person('secretary','提示与带路都不耗时','large')}<div class="quote">${esc(h.text)}</div>${t?followButton(t,'带我找到对应位置','primary full'):B('查看经营总结','company','','primary full')}<div class="note guide-note">点击带路后，对应的房间、按钮或来信会出现闪动金框。你来点击和决定，我负责指出位置。</div><div class="toolbar">${B('看看当前风险预测','company','','ghost')}${B('我先自己看看','close','','ghost')}</div>`,{kind:'secretary',kicker:'秘书随行 · 一次只指引下一步'});}
function companyLegacy(tab='overview'){if(tab==='jobs'){modal('部门排期',person('secretary','先保住结局前能用上的结果。')+jobsHTML(),{kind:'jobs',kicker:'第'+S.day+'天 · 第25天结束本轮'});return;}const b=I.finances(S);let body='';if(tab==='log'){body=`<div class="causal-list">${S.log.slice().reverse().map(l=>`<article><span class="day-tag">D${l.day}</span><div><h3>${esc(l.title)}</h3><p>${esc(l.text)}</p>${l.delta.cash?`<b class="${l.delta.cash>0?'good':'danger'}">现金 ${l.delta.cash>0?'+':''}${l.delta.cash}万</b>`:''}</div></article>`).join('')}</div>`;}
else{body=`${person('secretary',S.phase==='night'?'今天的结果与明天的风险，我替你整理好了。':'先看现金缓冲，再看准备情况。')}<div class="overview-duo"><section><div class="finance-hero"><div><small>可用现金</small><strong>${b.cash}<span>万</span></strong></div><div><small>今日变化</small><b class="${b.today>=0?'good':'danger'}">${b.today>0?'+':''}${b.today}万</b></div></div>${cashChart(b)}</section><section>${progressTrack()}<div class="paper-heading">交付准备，一眼看清</div><div class="readiness-grid">${I.readiness(S).map(x=>`<div class="readiness ${x.status}"><span>${x.status==='done'?icon('check'):x.status==='attention'?icon('shield'):icon('clock')}</span><b>${x.label}</b><small>${x.text}</small></div>`).join('')}</div></section></div>${S.phase==='night'?tomorrowCard():''}<div class="paper-heading">${S.phase==='night'?'秘书的明日预测':'秘书的风险提醒'}</div><p class="source">根据已知证据和当前安排预测，不是宣布某件事必定发生。</p>${I.forecast(S).map(r=>riskCard(r)).join('')}<div class="paper-heading">知识产权与商业回款</div>${businessSummary()}<details><summary>合作、技术与口碑</summary>${[['合作信任',S.trust],['技术自主空间',S.control],['市场口碑',S.reputation]].map(([l,n])=>`<div class="report-line"><div class="row spread"><b>${l}</b><span>${n}/100</span></div><div class="bar"><i style="width:${n}%"></i></div></div>`).join('')}<p class="source">以上为游戏经营指标，不代表法律有效性。</p></details><details ${tab==='cash'?'open':''}><summary>展开现金流水</summary><table class="money-table"><thead><tr><th>日期</th><th>事项</th><th>万元</th></tr></thead><tbody><tr><td>开局</td><td>专项额度</td><td>${(S.cash-S.ledger.reduce((n,x)=>n+x.amount,0)).toFixed(1)}</td></tr>${S.ledger.map(l=>`<tr><td>D${l.day}</td><td>${esc(l.why)}</td><td>${l.amount>0?'+':''}${l.amount}</td></tr>`).join('')}</tbody></table></details><details ${tab==='jobs'?'open':''}><summary>部门排期与明日交付</summary>${jobsHTML()}</details>`;}
modal(S.phase==='night'?'夜间经营简报':'公司经营总览',`<div class="tabs">${B('图形总览','company','overview',tab!=='log'?'active':'')}${B('决策记录','company','log',tab==='log'?'active':'')}</div>${body}<div class="toolbar dialog-footer">${B('回到现场','close','','primary')}${!S.ending?B('申请一次专项支持','stopAsk','','ghost'):''}</div>`,{wide:true,kind:'company',kicker:'第'+S.day+'天 · 经营结果与风险预测'});}
function docs(tab='contract'){let body;if(tab==='topics')body=`<p class="small">课程知识分布在不同任务与路线中。${S.topics.length} / ${C.topics.length} 个主题已通过本局行动接触；不要求为了点亮全部主题牺牲经营目标。</p>${C.topics.map(t=>`<button class="task-row" data-a="topic" data-id="${t[0]}"><span class="status-dot ${S.topics.includes(t[0])?'':'faded'}"></span><div class="grow"><strong>${esc(t[1])}</strong><small>${esc(t[2])} · ${S.topics.includes(t[0])?'本局已实践':'可在其他任务或路线实践'}</small></div><span class="arrow">›</span></button>`).join('')}`;else if(tab==='contract')body=contractHTML();else{const r=Object.values(S.reports).sort((a,b)=>b.day-a.day);body=r.length?r.map(r=>`<button class="task-row" data-a="report" data-id="${r.id}" ${!r.read&&S.phase==='day'?'disabled':''}>${icon('folder')}<div class="grow"><strong>${esc(r.title)}</strong><small>第${r.day}天 · ${r.read?'已归档':S.phase==='day'?'今晚统一汇报':'今晚待汇报'}</small></div>${!r.read?'<span class="badge">新</span>':'<span class="arrow">›</span>'}</button>`).join(''):'<div class="empty">这里会保留审计、尽调、FTO、研发和验收等报告。部门完成工作后送达，开局不会预先提供调查结论。</div>';}modal('公司资料库',`<div class="tabs">${[['contract','合作档案'],['topics','课程知识']].map(([id,l])=>`<button class="${id===tab?'active':''}" data-a="${id==='topics'?'topicArchive':'contractArchive'}">${l}</button>`).join('')}</div>${body}`,{wide:tab==='contract',kind:'docs',kicker:'资料免费查阅 · 进度与证据保留'});}
function contractHTML(){return `${briefHTML()}<div class="paper-heading">董事会统一目标</div><p>${({direct:'自主交付优先：标杆客户、直接关系与核心选择。',partner:'共同扩张：伙伴能力、投入治理与成果安排。',network:'许可与服务网络：持续收入、标准与使用核查。'})[S.flags.route]||'等待首次战略会议。'}</p><div class="paper-heading">优先资产</div>${S.assets.length?S.assets.map((id,i)=>`<p class="report-line">${i+1}. ${esc(C.assets.find(a=>a.id===id).name)}</p>`).join(''):'<p class="small">尚未确定五项优先资产。</p>'}<div class="paper-heading">拟许可技术清单</div>${S.license.length?S.license.map(id=>`<p class="report-line">${esc(C.licenseAssets.find(a=>a[0]===id)[1])}${S.licenseModes?.[id]?' · '+(S.licenseModes[id]==='controlled'?'受控协作，不交完整副本':'限定交付副本'):''}</p>`).join(''):'<p class="small">尚未形成许可清单。</p>'}<div class="paper-heading">合作方式与条件</div><table class="money-table"><tbody><tr><td>治理方式</td><td>${({alliance:'技术联盟',joint:'联合开发',venture:'区域合资',equity:'股权投资'})[S.flags.governance]||'尚未确定'}</td></tr>${S.terms?Object.entries(S.terms).map(([k,v])=>`<tr><td>${({territory:'许可范围',exclusive:'独占条件',improvements:'新成果',sub:'分包',exit:'退出安排'})[k]}</td><td>${esc(({project:'新加坡项目 / 2年',regional:'东盟列名行业 / 3年',none:'非独占',performance:'有限独占与业绩节点',open:'区域独占，退出不清',split:'分别识别，约定互惠使用',shared:'共同使用，核对贡献',partner:'本地改进由伙伴控制',named:'限定列名对象',free:'伙伴自行增加',managed:'返还、撤权与服务衔接',later:'结束时再协商'})[v])}</td></tr>`).join(''):''}</tbody></table>${S.contract?`<div class="note" style="margin-top:18px">合同已经签署。总额${S.contract.value}万元，首付款${S.contract.deposit}万元已到账。后续款项见公司现金账。</div>`:S.offer?B('查看待接受的还价','offer','','primary full','style="margin-top:20px"'):'<p class="source">拟议清单与谈判不等于已签合同。</p>'}`;}
function topic(id){const t=C.topics.find(t=>t[0]===id);if(!t)return;const related=C.tasks.filter(x=>x.topics.includes(id));modal(t[1],`<span class="pill">${esc(t[2])}</span><p style="margin-top:17px">${esc(t[3])}</p><div class="rule"></div><div class="paper-heading">在企业里怎样实践</div>${related.map(x=>`<div class="report-line"><b>${esc(x.title)}</b><small style="display:block">${esc(C.places[x.place].name)} · ${S?S.completed[x.id]?'本局已做出决定':E.reason(S,x)||'可以开展':'开始游戏后探索'}</small><p class="small">${esc(x.brief)}</p></div>`).join('')}<div class="source">课件提供分析框架。游戏中的公司、权利编号、报价和时限是模拟设定。具体法律问题以对应国家、事实与当时规则为准。</div>`,{kicker:'知识产权策略 · 可选深入阅读'});}
function sources(){modal('课程、资料与美术来源',`${C.sources.map(([t,d,u])=>`<div class="report-line"><b>${esc(t)}</b><p class="small">${esc(d)}</p>${u?`<a href="${esc(u)}" target="_blank" rel="noopener noreferrer" class="small">查看原始资料 ↗</a>`:''}</div>`).join('')}<div class="report-line"><b>场景与人物</b><p class="small">依据已选定的商务美术方向，为本作生成14幅独立环境与10位人物的4种表情。画面文字、按钮与交互均为独立界面；人物与权利事件为虚构。背景音乐采用选定的三首授权曲目，场所环境声和操作音效独立控制；包含设备低鸣、纸张摩擦、来电压低配乐及签约落印。</p></div><div class="report-line"><b>配乐鸣谢 · Kevin MacLeod</b><p class="small">白天：Deep Haze（A2）；夜晚：Dream Culture（B1）；商战高潮：The Complex（A3）。作者 Kevin MacLeod，来自 Incompetech，按 CC BY 4.0 使用。游戏调整播放音量，并循环播放、交叉淡入淡出。</p><p class="small"><a href="https://incompetech.com/music/royalty-free/index.html?isrc=USUAN1100886" target="_blank" rel="noopener">Deep Haze</a> · <a href="https://incompetech.com/music/royalty-free/index.html?isrc=USUAN1300046" target="_blank" rel="noopener">Dream Culture</a> · <a href="https://incompetech.com/music/royalty-free/index.html?isrc=USUAN1300025" target="_blank" rel="noopener">The Complex</a> · <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener">许可说明</a></p></div><div class="report-line"><b>课程覆盖方式</b><p class="small">四份所提供课件的实质教学主题，映射到${C.tasks.length}项经营工作、${C.events.length}类条件事件及不同结局。单局根据路线接触一部分；手机报告中的课程档案可查完整主题。课程中重复页、目录与课堂行政信息不作为关卡。</p></div>`,{kicker:'教学素材与原创游戏内容分别标示'});}
function help(){modal('怎样经营这二十五天',`<div class="stack"><div class="note">你的目标：完成新加坡项目，并决定华东是否、怎样进入下一市场。你负责资源、证据与承诺。</div>${[['01','找对人','点击“现场 → 选择地点”，了解职责再决定实际拜访。没有当前事项的拜访只会收到问候，并使用1次行动和1万元执行费用。'],['02','安排工作','白天有3次行动。现金不足时先检查一次紧急融资机会；仍无法周转才结束经营。每项决策与委派使用1次，跨城出差使用2次。不同部门可以并行，一个部门的工作按顺序排队。'],['03','读报告，再判断','拿到调查报告不等于风险已处理。权属、伙伴尽调与FTO解决不同问题；需要根据事实选择整改、许可、替代或限定范围。'],['04','谈条件，兑承诺','技术清单、独占与新成果安排会改变伙伴还价。首付款签约后到账，阶段款取决于验收，尾款尚有后续条件。'],['05','晚上看图形简报','夜间回到家或住处，用电脑看经营分析，用手机处理一次紧急审批。读资料、看地图、询问秘书都不耗时。'],['06','处理意外，留下选择','合作订单、改进交易和疑似侵权事件带来新收入或新约束；风险事件仍按准备触发。第25天结束本轮。可以同一开局复盘，也可以尝试不同的商业局面。']].map(([n,t,d])=>`<div class="row" style="align-items:flex-start"><span class="task-number">${n}</span><div><h3>${t}</h3><p class="small">${d}</p></div></div>`).join('')}</div><div class="rule"></div><p class="small">阅读没有真实倒计时。关闭页面会保留本机进度，换手机请从设置导出存档再导入。原有第一版进度独立保留。</p>`,{kicker:'上手说明 · 可随时回来查看'});}
function settings(){modal('设置与存档',`<p class="small">白天 A2 · Deep Haze ／ 夜晚 B1 · Dream Culture<br>商战高潮 A3 · The Complex。三首均为 Kevin MacLeod 作品。</p><p id="music-status" class="source" role="status"></p><label class="field"><span>背景音乐 <output id="music-label">${Math.round(prefs.music*100)}%</output></span><input type="range" name="music" min="0" max="100" value="${prefs.music*100}" aria-label="背景音乐音量"></label><label class="field"><span>场所环境声 <output id="environment-label">${Math.round(prefs.environment*100)}%</output></span><input type="range" name="environment" min="0" max="100" value="${prefs.environment*100}" aria-label="场所环境声音量"></label><label class="field"><span>音效 <output id="effects-label">${Math.round(prefs.effects*100)}%</output></span><input type="range" name="effects" min="0" max="100" value="${prefs.effects*100}" aria-label="音效音量"></label><label class="choice-check"><input name="muted" type="checkbox" ${prefs.muted?'checked':''}><span>静音</span></label><div class="toolbar">${B('试听当前配乐','testSound','','ghost')}${B('玩法说明','help','','ghost')}${B('资料来源','sources','','ghost')}</div><div class="rule"></div><h3>本机进度与转移</h3><p class="small" style="margin-top:8px">V8自动保存在当前浏览器，导出后可换设备继续。V7保留原来的规则和存档，请到V7中继续旧进度；这里仅导入V8存档。</p><div class="toolbar" style="margin-top:15px">${B(icon('download')+'导出当前存档','export','','primary',S?'':'disabled')}${B('导入存档','import','','ghost')}${B('查看本机经营记录','history','','ghost')}</div>${S?`<p class="source">开局编号 ${S.seed} · ${S.actions.length}条有效操作</p>`:''}<div class="rule"></div><a href="v7/index.html" target="_blank" rel="noopener">打开保留的 V7</a>`,{kind:'settings',kicker:'音频在点击后启用 · 不联网生成剧情'});sound.musicStatus();}
function importDialog(){modal('导入经营存档',`<div class="note">导入会替换本机当前进度。V7原版不受影响；可以先导出当前存档。</div><label class="field"><span>选择游戏导出的 JSON 文件</span><input type="file" id="save-file" accept=".json,application/json"></label><label class="field"><span>也可以粘贴完整存档内容</span><textarea id="save-text" placeholder="粘贴从本游戏导出的存档内容" spellcheck="false"></textarea></label>${B('验证并导入存档','doImport','','primary full')}`,{kind:'import'});}
function history(){let h=[];try{h=JSON.parse(localStorage.getItem(HISTORY)||'[]');}catch{}modal('本机经营记录',h.length?h.slice().reverse().map(x=>`<div class="report-line"><h3>${esc(x.title)}</h3><small>开局${esc(x.seed)} · 第${esc(x.day)}天 · 结清现金${esc(x.cash)}万元</small></div>`).join(''):'<p class="empty">完成一局后，这里会保留结局与资金结果。对照同一开局，看看另一项选择改变了什么。</p>');}
function newGame(same=false){const seed=same&&S?S.seed:(crypto.getRandomValues(new Uint32Array(1))[0]||72317);let has=false;try{has=!!localStorage.getItem(KEY);}catch{}if(has){pending={newSeed:seed};modal(same?'同一开局，再经营一次':'开启新的商业局面',`<p>开始后将替换本机当前进度。${same?'保留相同外部条件，比较不同决策带来的后果。':'新的需求线索与事件组合会随开局变化。'}</p><div class="toolbar dialog-footer">${S?B('先导出当前存档','export','','ghost'):''}${B('开始这一局','startConfirmed','','primary')}${B('返回','close','','ghost')}</div>`);}else begin(seed);}
function beginLegacy(seed){clearTimeout(autoTimer);S=E.fresh(seed);lastBankruptcyPrompt=false;started=true;guide=null;view='scene';persist();close();sound.start();render();window.scrollTo({top:0});toast('80万元出海专项资金，每天3次行动。许知微随时可以带路。');}
function download(filename,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function clickAction(el){const a=el.dataset.a,id=el.dataset.id||'';if(el.disabled)return;sound.start();switch(a){
case 'choiceCommit':{const d=choiceDraft;if(!d)break;if(d.type==='task')submitTask(d.id,d.option);else{const payload=d.option==='pilot'?{scope:$('#business-scope').value,team:Number($('#business-team').value)}:undefined;const action={type:'event',id:d.id,option:d.option,payload};if(!timingGuard(action))run(action);}break;}
case 'timingProceed':{const action=timingDraft;if(action)run({...action,ackTiming:true});break;}
case 'cancelJobAsk':{const j=S.jobs.find(j=>j.id===id);if(!j)break;pending={type:'cancelJob',id};modal('撤回这项尚未开始的工作？','<p>这项工作原定第'+j.start+'天开始，第'+j.due+'天完成。前期费用已发生，不退还；撤回后会重新排后面的工作，相关预计回款也会取消；已经作出的合作承诺不会自动解除。</p><div class="toolbar">'+B('撤回并重新排期','execute','','primary')+B('继续保留','company','jobs','ghost')+'</div>',{kind:'cancel'});break;}
case 'workNext':close();maybePriority();break;
case 'close':clearTimeout(workTimer);close();break;
case 'new':newGame();break;
case 'replay':newGame(true);break;
case 'startConfirmed':begin(pending.newSeed);break;
case 'continue':try{clearTimeout(autoTimer);const raw=localStorage.getItem(KEY);S=E.load(raw);if(JSON.parse(raw).version<7&&!localStorage.getItem(KEY+'-before-v7'))localStorage.setItem(KEY+'-before-v7',raw);started=true;view=S.ending?'ending':'scene';persist();render();if(!S.ending)maybePriority();}catch(e){toast(e.message,true);}break;
case 'scene':close();view=S.ending?'ending':'scene';render();window.scrollTo({top:0});break;
case 'map':close();view='map';render();window.scrollTo({top:0});break;
case 'zoommap':mapWorld=!mapWorld;render();break;
case 'city':cityInfo(id);break;
case 'placeInfo':placeInfo(id);break;
case 'visit':if(run({type:'visit',place:id},false)&&S.log.at(-1)?.title==='无效拜访'){const p=C.places[id];modal('一次没有推进的拜访',`${person(p.person)}<div class="quote">您好。这里暂时没有与当前项目进度相符、需要您决定的事项。下次您可以先让许知微确认议程。</div><p class="note">这次拜访使用了1次行动和1万元执行费用。白天还有行动时可以继续前往其他地点；进入夜晚后可以复盘。</p>${B(S.phase==='night'?'回到住处':'继续今天的工作','close','','primary full','style="margin-top:18px"')}`,{kicker:p.name+' · 负责人向你问好'});}break;
case 'travelAsk':{const c=C.cities[id],cost=['singapore','malaysia'].includes(id)||['singapore','malaysia'].includes(S.city)?2:1;pending={type:'travel',city:id};modal('安排前往'+c.name,`<p>从${C.cities[S.city].name}前往${c.name}，出差费用${cost}万元，使用2次行动。如果到达后还有行动，可以当天开展现场工作。</p><div class="note" style="margin-top:16px">当前${S.phase==='day'?'剩余'+S.slots+'次行动':'已是夜间'}。手机可以先安排允许远程进行的工作。</div><div class="toolbar dialog-footer">${B('确认出发','execute','','primary',S.phase!=='day'||S.slots<2?'disabled':'')}${B('先留在这里','close','','ghost')}</div>`);break;}
case 'task':taskModal(id,el.dataset.remote==='1');break;
case 'taskBack':taskModal(activeTask,remoteTask,true);break;
case 'option':chooseDecision(el,true);break;
case 'submitTask':submitTask(id);break;
case 'assetUp':{const i=draft.indexOf(id);if(i>0)[draft[i-1],draft[i]]=[draft[i],draft[i-1]];$('#asset-list').innerHTML=assetChecklist();break;}
case 'assetRemove':draft=draft.filter(x=>x!==id);$('#asset-list').innerHTML=assetChecklist();break;
case 'execute':{const a=pending;if(run(a)){if(a.type==='task'&&C.taskById[a.id].type==='terms')offer();}break;}
case 'offer':offer();break;
case 'signAsk':pending={type:'acceptOffer'};modal('正式签署合作协议',`<p>当前还价、技术清单与合作条件将生效。治理投入${S.offer.governanceCost}万元，首付款${S.offer.deposit}万元到账。阶段交付需要继续兑现承诺。</p><div class="toolbar dialog-footer">${B('确认签署','execute','','primary')}${B('继续审议','offer','','ghost')}</div>`);break;
case 'event':eventView(id);break;
case 'eventAsk':chooseDecision(el,true);break;
case 'report':report(id);break;
case 'phone':phone(id||'oa');break;
case 'contact':contact(id);break;
case 'secretary':secretary();break;
case 'hint':secretary();break;
case 'docs':phone('reports');break;
case 'contractArchive':docs('contract');break;
case 'topicArchive':docs('topics');break;
case 'follow':startGuide({[el.dataset.type]:id});break;
case 'guideStop':guide=null;refreshGuide();break;
case 'company':company(id||'overview');break;
case 'topic':topic(id);break;
case 'meeting':break;
case 'question':case 'support':updateDebate(a,id,el.dataset.stage);break;
case 'momentNext':close();render();setTimeout(maybePriority,150);break;
case 'answerCall':sound.effect('answer');openLetter(id);break;
case 'deferCall':run({type:'readEvent',id},false);break;
case 'bankRestart':begin(S.seed);break;
case 'bankReview':close();company('log');break;
case 'help':help();break;
case 'sources':sources();break;
case 'settings':settings();break;
case 'testSound':{const ok=await sound.start();if(ok){sound.effect('confirm');toast(prefs.muted?'当前已静音，取消静音后可试听。':'已启用当前场景配乐。');}else toast('当前浏览器暂未能播放音频，游戏可以继续。',true);break;}
case 'endDay':pending={type:'endDay'};modal('结束今天的外出',`<p>今天还剩${S.slots}次行动，未使用的时段不会保留。回到住处后，可以复盘、看报告，并处理一次紧急审批。</p><div class="toolbar dialog-footer">${B('回到住处','execute','','primary')}${B('继续白天工作','close','','ghost')}</div>`);break;
case 'sleep':if(nightReports().length){report(nightReports()[0].id,true);break;}run({type:'sleep'});window.scrollTo({top:0});break;
case 'stopAsk':pending={type:'stop'};modal('提交当前经营结果',`<p>这会结束本轮，结清已借入的周转资金，并按已兑现交付和当前准备形成结局。尚未到期的工作与应收款不会自动完成。</p><div class="toolbar dialog-footer">${B('确认提交并结束本轮','execute','','danger')}${B('继续经营','close','','primary')}</div>`);break;
case 'export':if(S)modal('导出当前存档',`<p class="small">可以下载文件，也可以复制下面的存档文本，在另一台设备的导入窗口粘贴。</p><label class="field"><span>完整存档内容</span><textarea id="export-text" readonly spellcheck="false">${esc(JSON.stringify(E.save(S),null,2))}</textarea></label><div class="toolbar">${B('下载JSON文件','downloadSave','','primary')}${B('复制存档文本','copySave','','ghost')}</div>`,{kind:'export'});break;
case 'downloadSave':download('华东智行_第'+S.day+'天_开局'+S.seed+'.json',JSON.stringify(E.save(S),null,2));toast('已请求下载；若此浏览器不支持下载，可以复制存档文本。');break;
case 'copySave':try{await navigator.clipboard.writeText($('#export-text').value);toast('存档文本已复制。');}catch{$('#export-text').focus();$('#export-text').select();toast('请长按或使用复制，将选中的存档文本带到另一台设备。');}break;
case 'import':importDialog();break;
case 'doImport':try{clearTimeout(autoTimer);const next=E.load($('#save-text').value);S=next;lastBankruptcyPrompt=false;guide=null;started=true;view=S.ending?'ending':'scene';persist();close();render();toast('存档已经验证并恢复。');if(!S.ending)maybePriority();}catch(e){$('#modal-error').textContent=e.message;}break;
case 'history':history();break;
}}
function meetingPanel(id){const opinion=C.meeting.find(x=>x[0]===id)||C.meeting[0];return `<div class="meeting-people" role="group" aria-label="听取各部门意见">${C.meeting.map(([pid])=>`<button data-a="meeting" data-id="${pid}" class="${pid===opinion[0]?'selected':''}" aria-pressed="${pid===opinion[0]}">${portrait(pid,'small',1)}<span>${esc(C.people[pid].role.replace('负责人',''))}</span></button>`).join('')}</div><div class="meeting-voice" aria-live="polite"><b>${esc(C.people[opinion[0]].name)}的意见</b><p>${esc(opinion[1])}</p></div>`;}
function followButton(t,label,cl='ghost full'){const type=t.phone?'phone':t.event?'event':t.report?'report':t.task?'task':'place',id=t[type]||t.place;return B(esc(label||t.label||'查看下一步'),'follow',id,cl,`data-type="${type}"`);}
function suggestionRow(t){return followButton(t,(t.report?'读报告 · ':t.task?'去安排 · ':'查看 · ')+(t.label||C.taskById[t.task]?.title||''),'agenda-row');}
function waitingCard(){const jobs=S.jobs.filter(j=>['queued','running'].includes(j.status));return `<div class="empty-state">${icon(jobs.length?'clock':'people')}<h3>${jobs.length?'团队正在执行':'这里的当前事项已处理'}</h3><p>${jobs.length?'最近一份报告预计第'+Math.min(...jobs.map(j=>j.due))+'天送达。可以推进其他部门，或结束白天等待。':'换个地点、联系其他团队，或请秘书指出下一步。'}</p>${B('查看手机待办','phone','','ghost')}${B('请秘书带路','secretary','','ghost')}</div>`;}
function progressTrack(){const f=S.flags;const steps=[['战略',!!S.completed.strategy],['调查',!!f.ftoClear&&!!f.ddFixed],['签约',!!S.contract],['交付',!!f.delivered],['下一站',!!f.nextReady]];return `<div class="progress-track" aria-label="经营进度">${steps.map(([l,done],i)=>`<div class="${done?'done':''}"><span>${done?'✓':i+1}</span><small>${l}</small></div>`).join('')}</div>`;}
function riskCard(r,short=false){return `<article class="risk-card ${r.level}"><div class="risk-heading"><span class="risk-mark">${r.level==='high'?'优先':r.level==='watch'?'关注':'提示'}</span><b>${esc(r.label)}</b></div><p>${esc(r.detail)}</p>${!short&&r.target?followButton(r.target,'找到对应处理位置','text-action'):''}</article>`;}
function cashChart(b){const max=Math.max(b.cash,b.committed+b.daily,1);return `<div class="cash-chart" role="group" aria-label="资金缓冲图"><div class="cash-chart-row"><span>现在可用</span><div class="chart-track"><i style="width:${Math.max(0,b.cash)/max*100}%"></i></div><b>${b.cash}万</b></div><div class="cash-chart-row committed"><span>已知承诺</span><div class="chart-track"><i style="width:${(b.committed+b.daily)/max*100}%"></i></div><b>${Math.round((b.committed+b.daily)*10)/10}万</b></div><div class="cash-buffer"><span>扣除后缓冲 <b class="${b.buffer<15?'danger':'good'}">${b.buffer}万</b></span><small>含交付、周转偿还与剩余日常费用；不含新增决定。</small></div><div class="receivable">${icon('clock')} ${b.receivable?b.receivable+'万元后续款仍有条件，未计入可用现金':'尚无待收合同款'}</div></div>`;}
function resolveGuide(target){let t={...target};for(let n=0;n<10&&t.task;n++){const task=C.taskById[t.task];if(!task){toast('当前没有这项工作。',true);return null;}if(E.available(S,task))return t;const job=S.jobs.find(j=>j.task===task.id&&['queued','running'].includes(j.status));if(job){guide=null;close();company('jobs');toast('这项工作已委派，预计第'+job.due+'天送达报告。');return null;}const missing=task.needs.find(k=>k[0]==='@'?!S.reports[k.slice(1)]?.read:!S.completed[k]);if(missing){if(missing[0]==='@'&&S.reports[missing.slice(1)])return {report:missing.slice(1)};if(missing==='contract')return {place:'partner'};t={task:missing.replace('@','')};continue;}const next=I.nextActions(S)[0];if(!next||next.task===t.task){guide=null;close();phone('oa');toast('这项安排已完成，待办中保留了当前可继续的工作。');return null;}t=next;}return t;}
function startGuideOld(target){if(target.phone){phone(target.phone);return;}target=resolveGuide(target);if(!target)return;guide={...target};close();if(guide.event){phone('oa');}else if(guide.report){phone('reports');}else{const task=guide.task&&C.taskById[guide.task];const place=task?.place||guide.place;guide.place=place;if(!C.places[place]){guide=null;toast('这项工作暂时没有可定位的位置。',true);return;}if(S.phase==='night'){if(task?.night&&!S.nightUsed)phone('oa');else{guide=null;company();toast('现在是夜晚，现场工作明天继续；先看简报与风险。');return;}}else if(S.place===place){view='scene';render();}else if(task?.remote&&C.places[place].city!==S.city){phone('oa');}else if(S.place==='hq'&&C.places[place].city==='suzhou'){view='scene';render();}else{view='map';render();}}setTimeout(refreshGuide,80);}
function refreshGuide(scroll=false){document.querySelectorAll('.guided-target').forEach(e=>e.classList.remove('guided-target'));document.querySelectorAll('.guide-banner').forEach(e=>e.remove());if(!guide||!S||S.ending)return;const scope=dialog.open?dialog:$('#app');let selector='';if(dialog.open&&modalKind==='phone'){const who=guide.event?C.eventById[guide.event]?.person:guide.task?C.taskById[guide.task]?.person:guide.report?C.taskById[guide.report]?.person:null;selector=who?'[data-a="contact"][data-id="'+who+'"]':'';}else if(guide.event)selector=`[data-a="event"][data-id="${guide.event}"]`;else if(guide.report)selector=`[data-a="report"][data-id="${guide.report}"]`;else{const t=guide.task&&C.taskById[guide.task],place=t?.place||guide.place,city=C.places[place]?.city;if(dialog.open){if(scope.querySelector(`[data-a="task"][data-id="${guide.task}"]`))selector=`[data-a="task"][data-id="${guide.task}"]`;else if(scope.querySelector('[data-a="execute"]')&&((pending?.type==='task'&&pending.id===guide.task)||(pending?.type==='travel'&&pending.city===city)||(pending?.type==='acceptOffer'&&place==='partner')))selector='[data-a="execute"]';else if(scope.querySelector(`[data-a="visit"][data-id="${place}"]`))selector=`[data-a="visit"][data-id="${place}"]`;else if(scope.querySelector(`[data-a="travelAsk"][data-id="${city}"]`))selector=`[data-a="travelAsk"][data-id="${city}"]`;else selector=`[data-a="placeInfo"][data-id="${place}"]`;}else if(S.place===place&&view==='scene'){selector=S.offer&&!S.completed.contract&&place==='partner'?'[data-a="offer"]':`[data-a="task"][data-id="${guide.task}"]`;}else if(city===S.city)selector=`[data-a="placeInfo"][data-id="${place}"]`;else selector=`[data-a="city"][data-id="${city}"]`;}
const el=selector&&scope.querySelector(selector);if(!el||el.disabled)return;for(let d=el.closest('details');d;d=d.parentElement?.closest('details'))d.open=true;el.classList.add('guided-target');el.setAttribute('data-guide-note','秘书指引的位置');const banner=document.createElement('div');banner.className='guide-banner';banner.setAttribute('role','status');banner.innerHTML=`<span>跟着金色闪光，点击对应位置</span>${B('结束指引','guideStop','','ghost')}`;if(dialog.open)dialog.querySelector('.dialog-head').after(banner);else document.querySelector('.mission').after(banner);if(scroll)el.scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}
function maybePriorityOld(){if(!started||!S||S.ending||dialog.open)return;const next=S.events.find(e=>e.id==='accessrequest'&&e.status==='open'&&e.seen!==e.status)||S.events.find(e=>['open','report'].includes(e.status)&&e.seen!==e.status);if(next){guide=null;if(next.id==='accessrequest'&&next.status==='open'){incomingCall(next.id);}else{sound.effect('ring');eventView(next.id);}}}
