function openLetterLegacy(id){if(!S.events.some(e=>e.id===id))return;run({type:'readEvent',id},false);const e=S.events.find(e=>e.id===id),d=C.eventById[id],open=['open','report'].includes(e.status),allowed=S.phase==='day'||!S.nightUsed,labels=eventApproaches[id]||[],opportunity=['earlydemo','newclient','competitor'].includes(id);let choices=[];
if(e.status==='open'&&!E.eventOptions(S,e))choices=[['investigate',labels[0],'安排1天核查；部门繁忙时顺延。',2],['contain',labels[1],'先投入临时安排，再取得核查结果。',5],['ignore',labels[2],opportunity?'放弃或推迟这次机会，既有项目继续。':'不解决当前缺口，关系或协调成本保留。',id==='newclient'?0:5]];
if(e.status==='report'&&!E.eventOptions(S,e))choices=[['fix',d.fix,'按调查结果执行，影响会记入夜间简报。',d.cost],['reduce',opportunity?'缩小本次机会投入，保住现有交付':'缩小本轮承诺与交付',opportunity?'暂不扩大新机会，不削减已签项目金额。':'可能减少本轮验收范围和金额。',3],['leave','暂不落实这次后续处置','保留未决事项或放弃本次机会。',1]];
modal(d.title,`<div class="letter-meta">${portrait(d.person,'small')}<div><b>来自 ${esc(C.people[d.person].name)}</b><small>${esc(C.people[d.person].role)} · 第${e.day}天</small></div><span class="letter-stamp">${open?'第'+e.due+'天前回复':e.status==='investigating'?'调查中':e.status==='working'?'团队作业中':e.status==='settling'?'履约中':'已归档'}</span></div><div class="letter-progress"><span class="done">收到来信</span><span class="${e.status!=='open'?'done':''}">核实情况</span><span class="${!['open','report','investigating','settling','working'].includes(e.status)?'done':''}">落实决定</span></div><p class="letter-fact">${esc(e.fact||d.fact)}</p>${!d.v5&&['report','resolved','contained'].includes(e.status)?`<div class="letter-report"><b>团队带回的证据</b><p>${esc(d.report)}</p></div>`:''}${e.status==='settling'?`<div class="letter-report"><b>履约中 · 暂未计入现金</b><p>团队已执行本次约定，预计第${e.payDay}天核对${e.expected}万元交易款。实际结果到期揭晓。</p>${B('查看排期','company','jobs','ghost')}</div>`:''}${e.result?`<div class="letter-report"><b>本次处理结果</b><p>${esc(e.result)}</p></div>`:''}${['investigating','working'].includes(e.status)?`<div class="note">团队已接手，结果按排期送达。${B('查看部门排期','company','jobs','ghost')}</div>`:''}${open&&!allowed?'<div class="note">今晚的审批已经用完。来信保存在手机待办，明天可继续处理。</div>':''}${businessChoices(e)||''}<div class="letter-options">${choices.map(([op,title,desc,cost])=>`<button class="choice" data-a="eventAsk" data-id="${id}" data-option="${op}" ${allowed?'':'disabled'}><strong>${esc(title)}</strong><p>${esc(desc)}</p><div class="cost">${cost}万元 · ${S.phase==='night'?'今晚1次审批':'1次行动'} · 先看我的判断</div></button>`).join('')}</div>${B(open?'稍后处理，保留在手机待办':'返回当前工作','close','','ghost full')}<details><summary>相关知识与依据</summary>${sourceTags([d.topic])}</details>`,{kind:'event',kicker:e.status==='report'?'新邮件 · 调查结果已到':'新邮件 · 优先处理'});sound.effect('paper');}

function characterMood(id){if(S?.ending)return S.ending.id==='bankrupt'||S.ending.id==='retreat'?2:3;if(S?.events.some(e=>['open','report'].includes(e.status)&&!C.eventById[e.id]?.commercial))return id==='secretary'||id==='legal'||id==='hr'?2:1;const support=S?.board?.[activeTask==='license'?'license':'strategy']?.support;if(support===id)return 3;return S?.phase==='night'?1:S?.flags.signed&&id==='partner'?3:0;}
function contextLine(id){const f=S.flags;if(id==='hardware'&&f.siteHardware)return f.prototypeProof?'现场复测数据在这里。把改进卖一次，还是保留多次许可，是两种生意。':'峰值瓶颈已经找到。下一步可以把线索变成可展示的改进。';if(id==='algorithm'&&f.siteAlgorithm)return f.modelProof?'模型已经用真实异常样本验证；可以给潜在客户看限定的性能证据。':'现场演练说明：临时排障也必须有名单和访问记录。';if(id==='hr'&&f.staffVacancy)return f.handoverDone?'工位空了，但交接已经完成。公司不能只靠一个人记住关键技术。':'适配席位正在调整，下一班人手和权限需要你安排。';if(id==='partner'&&f.signed)return f.accessManaged?'受控排障已经完成。下一次申请我们会先提交列名人员。':'协议已经生效。现在看双方能否兑现人员和交付承诺。';if(id==='finance'&&S.business?.income)return '本局新增商业回款'+S.business.income+'万元；未到期交易款仍不算可用现金。';return C.people[id].line;}
