const other=id==='legal'||id==='finance'?'market':'legal';const reply=other==='market'?'我会据此重谈时间和范围，但需要你给出明确优先项。':'可以推进，同时把实际范围和未决条件写清，避免口头承诺扩大。';
return '<div class="debate-header"><span class="live-dot"></span><b>'+ (stage==='license'?'技术开放争议':'海外战略会')+'</b><small>追问与表态不耗时</small></div><div class="meeting-people" role="group" aria-label="选择追问的负责人">'+['market','legal','hardware','finance','hr','chair'].map(pid=>'<button data-a="question" data-id="'+pid+'" data-stage="'+stage+'" class="'+(pid===id?'selected':'')+'" aria-pressed="'+(pid===id)+'">'+portrait(pid,'small',pid===b.support?3:pid===id?1:0)+'<span>'+esc(C.people[pid].role.replace('负责人',''))+'</span><small>'+(b.asked.includes(pid)?'已追问':'追问')+'</small></button>').join('')+'</div><div class="debate-exchange" aria-live="polite"><p class="ceo-question">你：'+questions[id]+'</p><div class="speech-row">'+portrait(id,'small',1)+'<div><b>'+C.people[id].name+'</b><p>'+answers[id]+'</p></div></div><div class="speech-row response">'+portrait(other,'small',2)+'<div><b>'+C.people[other].name+' 接话</b><p>'+reply+'</p></div></div></div><div class="support-row"><span>你的表态</span>'+B(b.support===id?'已支持这个优先项':'支持'+C.people[id].role+'的优先项','support',id,'ghost','data-stage="'+stage+'" '+(stage==='license'&&S.flags.licensePriority?'disabled':''))+'</div><p class="small debate-note">'+(b.support?'许知微记录：优先听取'+C.people[b.support].role+'的依据。正式决定后会影响团队取向。':'可以先追问其他人，再表态。正式经营方案仍由你在下方决定。')+'</p>';
