const MINI={documents:['授权文件找疑点','拿起放大镜，在三份材料里找出5处需要法务复核的地方。'],road:['专利路线沙盘','把两个已发现的路障接上一条处理路线。'],box:['技术交付箱','点选每项技术，决定伙伴能用到哪一步。'],lab:['设备压力测试','调节负载和散热模块，让设备达到要求并稳定运行。'],bargain:['三轮筹码桌','每一轮换一个条件，看看伙伴愿意付出什么。']};
function openMini(id,next=null){if(!X.miniAvailable(S,id)){toast('这项互动已经完成，或还没有相关材料。');return;}miniNext=next;miniDraft={id,found:[],route:[null,null],permissions:{runtime:'use',adapt:'use',core:'keep',data:'keep'},load:80,module:0,tested:false,deals:[],hint:''};paintMini();}
const docRisks=[['许可公司','合作方为“新智链科技”，授权收件人却写着“新智链咨询”。','名称相近，也要核对是否同一个签约主体。'],['使用地区','项目部署在新加坡，现有文件写的是“仅限中国境内”。','新加坡这次部署，有没有另行获准？'],['文件期限','该项许可已于去年到期，续期文件尚未附上。','先看有没有新的续期证明，不能只看旧印章。'],['技术交付','拟把源代码交给伙伴，但上游许可仅允许使用运行版本。','能使用，不代表可以把源代码继续交出去。'],['现场人员','现场分包团队在项目名单中，却未出现在获准使用名单里。','查查这些人有没有另获授权，别自动替他们作保证。']];
function paintMini(){const m=miniDraft;if(!m)return;const [title,desc]=MINI[m.id];let body='';if(m.id==='documents'){body=`<div class="magnifier-bar"><span class="magnifier-icon">⌕</span><b>已圈出 ${m.found.length} / 5 处</b><small>点击可疑文字圈出来</small></div><div class="document-desk">${['合作摘要','现有许可','实施附件'].map((title,col)=>`<article class="risk-document"><small>档案 0${col+1}</small><h3>${title}</h3><button class="document-clause doc-safe" data-v6="safeClause"><b>项目编号一致</b><p>材料均列明HD-SG-01，供本轮合作评估。</p></button>${docRisks.map(([label,text],i)=>i%3===col?`<button data-v6="findRisk" data-id="${i}" class="document-clause ${m.found.includes(i)?'found':''}"><b>${label}</b><p>${text}</p>${m.found.includes(i)?'<span>已圈出 · 待复核</span>':''}</button>`:'').join('')}<p class="doc-neutral">经办人已留存原件<br>附件请与授权主体核对</p></article>`).join('')}</div>`;}
if(m.id==='road'){body=`<div class="route-sandbox"><div class="route-destination">产品原型 → 两处已知专利障碍 → 可验证交付路线</div>${['通信网关','预测维护'].map((name,i)=>`<section class="road-row"><strong>${name}</strong><div class="patent-obstacle">已有权利线索<br><small>需要处理</small></div><div class="route-choices">${[['license','购买许可','花钱少改动'],['design','换一种设计','耗时，需要复测'],['trim','暂不做此功能','少花钱，功能变少']].map(([k,t,n])=>`<button data-v6="route" data-id="${i}:${k}" class="route-chip ${m.route[i]===k?'selected':''}">${t}<small>${n}</small></button>`).join('')}</div><div class="route-wire ${m.route[i]?'connected':''}">${m.route[i]?'已连接':'待接通'}</div></section>`).join('')}</div>${ceo('没有免费的通行证。我可以花钱买时间，也可以改设计，或者这次少做一点。','这张沙盘先定处理方向，正式费用和排期由法务与研发核实。')}`;}
if(m.id==='box'){const label={use:'可以使用',modify:'可以修改',keep:'留在公司'};body=`<div class="delivery-box"><div class="box-lid">新智链 · 本次交付箱</div><div class="tech-items">${[['runtime','运行程序','设备能运行'],['adapt','适配工具','伙伴自己接入现场'],['core','核心算法','公司最关键的实现'],['data','内部训练资料','原始样本与训练配方']].map(([k,t,n])=>`<button class="tech-token permission-${m.permissions[k]}" data-v6="permission" data-id="${k}"><b>${t}</b><small>${n}</small><span>${label[m.permissions[k]]}</span></button>`).join('')}</div></div><p class="small">点一项切换权限：可以使用 → 可以修改 → 留在公司。正式许可前仍要确认我们有权开放。</p>${ceo(m.permissions.core==='keep'?'核心还握在我们手里，伙伴遇到深层故障时可能更依赖团队支持。':'伙伴能动核心，自己解决问题会更快；我得接受技术暴露得更多。','交付要够用，边界也要说得清。')}`;}
if(m.id==='lab'){const heat=Math.round(m.load*1.05-m.module*16),stable=heat<=75&&m.load>=55;body=`<div class="lab-bench ${m.tested?stable?'stable':'overheat':''}"><div class="lab-device"><div class="device-core"></div><div class="device-indicator"></div><strong>${m.tested?(stable?'运行稳定':'需要再调整'):'等待试运行'}</strong></div><div class="lab-readouts"><div>负载 <b>${m.load}%</b><meter min="0" max="100" value="${m.load}"></meter></div><div>温度 <b>${m.tested?heat+'°C':'—'}</b><meter min="0" max="110" value="${m.tested?heat:0}"></meter></div></div></div><label class="field"><span>试验负载（目标至少55%）</span><input id="lab-load" aria-label="试验负载" type="range" min="30" max="100" step="5" value="${m.load}"></label><div class="toolbar">${[0,1,2].map(n=>V(['基础散热','加装风扇','升级散热组'][n],'module',n,m.module===n?'primary':'ghost')).join('')}</div><p class="small">稳定条件：温度不高于75°C，并达到基本负载。这里只测试方案，实际采购在后续决策确认。</p>${V('启动试运行','labTest','','primary full')}`;}
if(m.id==='bargain'){body=`<div class="bargain-table">${person('partner')}<div class="partner-says">${m.deals.length===0?'你们想保留技术，我希望换来确定的市场机会。先谈一项？':m.deals.length===1?({cash:'付款可以谈，你们需要给出清楚的验收节点。下一项谈市场和投入。',staff:'我可以安排人，但培训和职责要说清。下一项谈市场和投入。',freedom:'项目先做小一点也行，前期投入会少些。下一项谈市场和投入。'})[m.deals[0]]:m.deals.length===2?'最后一项，我们得给合作留一个能进能退的边界。':'三轮意向已经记下。正式报价时，我们会把投入、地域和退出条件一起核对。'}</div><div class="dealt-chips">${m.deals.map((x,i)=>`<span>第${i+1}轮 · ${({cash:'预付款优先',staff:'伙伴派人',freedom:'保持灵活'})[x]}</span>`).join('')}</div>${m.deals.length<3?`<div class="bargain-chips">${([[['cash','争取更多预付款','我们把阶段验收节点写清楚'],['staff','先谈本地人手','我们提供培训，伙伴承诺派人'],['freedom','先保留拓客空间','接受较少前期投入，保留其他客户']],[['cash','把付款与小里程碑挂钩','阶段更细，对方考虑提前付款'],['staff','用有限独占换团队','做不到约定业绩，我们可以换伙伴'],['freedom','只谈列名项目','不交出整个区域，双方先试一站']],[['cash','分期结算，减少拖欠','增加过程记录，争取更稳的回款'],['staff','约定双人交接','伙伴派备份，我们培训并记录权限'],['freedom','留下退出通道','已完成部分照结算，资料与权限归还']]][m.deals.length]).map(([k,t,n])=>V(`<strong>${t}</strong><small>${n}</small>`,'deal',k,'negotiation-chip')).join('')}</div>`:''}</div>${ceo('我不可能同时拿到最多的钱、最多的人，还不给对方任何条件。','先把最需要的换回来，再把边界写进合同。')}`;}
const valid=m.id==='documents'?m.found.length===5:m.id==='road'?m.route.every(Boolean):m.id==='lab'?m.tested:m.id==='bargain'?m.deals.length===3:true;const footer=`${m.hint?`<div class="secretary-hint">${portrait('secretary','small')}<p>${esc(m.hint)}</p></div>`:''}<div class="mini-footer">${V('问问许知微','miniHint','','ghost')}${V('交给团队复核 · 1万元','miniDelegate','','ghost',S.cash>=1?'':'disabled')}${V(m.id==='lab'?'记录测试，继续经营':'保存判断，继续经营','miniDone','','primary',valid?'':'disabled')}</div><p class="source">本局第${X.miniIds.indexOf(m.id)+1}类互动 · 不重复消耗行动 · 可补查和调整</p>`;
modal(title,`<p class="mini-intro">${desc}</p>${body}${footer}`,{wide:true,kind:'mini',kicker:'亲自看一眼 · 然后交给专业团队验证'});miniDraft=m;}
function miniComplete(delegated=false){const m=miniDraft;if(!m)return;const next=miniNext,payload=delegated?{delegated:true}:m.id==='documents'?{found:m.found}:m.id==='road'?{route:m.route}:m.id==='box'?{permissions:m.permissions}:m.id==='lab'?{load:m.load,module:m.module}:{deals:m.deals};if(run({type:'mini',id:m.id,payload},false)){miniNext=null;toast(S.minis[m.id].detail);if(next)setTimeout(next,300);}}
function renderEnding(){const e=S.ending,scene=({asean:'malaysia',foothold:'port',equity:'board',preserve:'chengdu',setback:'home',bankrupt:'hq'})[e.id]||'hq';const human={asean:['market','区域客户想安排下一次会谈。这回，我们有自己的交付案例了。'],foothold:['client','现场已经跑起来了。下一步服务，我们继续对接。'],equity:['finance','资金到账了。下一次董事会，也会有新股东参与。'],preserve:['algorithm','资料和团队都回来了。我们把这次问题继续做下去。'],setback:['secretary','所有决定都留在记录里。我们可以从最关键的一步重新推演。'],bankrupt:['secretary','最后一份资料已经归档。今天，先到这里。']}[e.id];return `<section class="ending-cinema ending-${e.id}" aria-label="${esc(e.title)}"><div class="ending-world"><img src="${asset(scene)}" alt="${esc(e.summary)}"><div class="ending-atmosphere"></div>${e.id==='asean'?'<div class="asean-routes"><span>新加坡</span><i></i><span>马来西亚</span><i></i><span>东盟 · 机会待验证</span></div>':''}${e.id==='bankrupt'?'<div class="closing-sign">停止新增经营</div>':''}<div class="ending-caption"><small>本轮经营答卷 · D${S.day}提交</small><h1>${esc(e.title)}</h1><p>${esc(e.summary)}</p></div><div class="ending-person">${person(human[0])}<p>${esc(human[1])}</p></div>${V('跳过镜头，查看复盘','endingSkip','','ghost ending-skip')}</div><div class="ending-reflection">${ceo(e.ceo,e.memories.join(' '))}<article class="ending-paper"><div class="news-masthead">商界观察 <small>本轮经营回顾</small></div><h2>${esc(e.newspaper)}</h2><div class="ending-metrics"><div><strong>${S.cash}</strong><small>项目现金 / 万元</small></div><div><strong>${Math.round(S.market.founder/S.market.shares*100)}%</strong><small>创始方持股</small></div><div><strong>${Object.keys(S.minis).length}/5</strong><small>现场互动</small></div><div><strong>${S.reputation}</strong><small>市场评价</small></div></div><p>${esc(e.future||'下一次，你会从哪个决定开始改变？')}</p></article><div class="toolbar">${B('重新开始，同一局面','replay','','primary')}${B('开启新的商业局面','new','','ghost')}${V('重看结局动画','endingReplay','','ghost')}${B('查看决策记录','company','log','ghost')}${B('导出本轮存档','export','','ghost')}</div></div></section>`;}
// All added controls share one delegated handler, leaving legacy business forms intact.
document.addEventListener('click',e=>{const el=e.target.closest('[data-v6]');if(!el||el.disabled)return;e.preventDefault();e.stopImmediatePropagation();const a=el.dataset.v6,id=el.dataset.id;try{sound.start();sound.effect('click');switch(a){case'phoneMessages':phone();break;case'phoneContacts':phone('team');break;case'boardStart':boardCinema();break;case'boardNext':introStep=Math.min(5,introStep+1);boardSpeech();break;case'boardDecide':run({type:'introSeen'},false);taskModal('strategy');break;case'capital':capital();break;case'news':newsArchive();break;case'trade':{const [kind,value]=id.split(':');const q=X.capitalQuote(S,kind,Number(value));if(!q.ok){toast(q.reason,true);break;}modal('确认本次股权操作',`${ceo(kind==='issue'?'这笔融资会进入公司，也会稀释原股东的份额。':'回购能收回一部分股份，也会减少可用现金。')}<div class="capital-preview"><p>现金变化：${q.net>0?'+':''}${q.net}万元</p><p>创始方持股：${q.before}% → ${q.after}%</p><p>执行费用：${q.fee}万元 · 不耗行动和审批 · 今晚唯一一笔交易</p></div>${V('确认执行','tradeCommit',id,'primary full')}`,{kind:'capitalConfirm'});break;}case'tradeCommit':{const [kind,v]=id.split(':');if(run({type:'capital',kind,amount:Number(v)}))capital();break;}case'rescue':run({type:'rescue',accept:id==='yes'});break;case'workDetail':workDetail(id);break;case'mini':openMini(id);break;case'safeClause':miniDraft.hint='这一处项目编号是对得上的。再看看谁能用、在哪里用，以及能交出什么。';paintMini();break;case'findRisk':if(!miniDraft.found.includes(Number(id))){miniDraft.found.push(Number(id));miniDraft.hint=docRisks[Number(id)][2];sound.effect('paper');}paintMini();break;case'route':{const [i,k]=id.split(':');miniDraft.route[Number(i)]=k;paintMini();break;}case'permission':{const states=['use','modify','keep'];miniDraft.permissions[id]=states[(states.indexOf(miniDraft.permissions[id])+1)%3];paintMini();break;}case'module':miniDraft.module=Number(id);miniDraft.tested=false;paintMini();break;case'labTest':miniDraft.tested=true;sound.effect('equipment');paintMini();break;case'deal':miniDraft.deals.push(id);sound.effect('stamp');paintMini();break;case'miniHint':{const m=miniDraft;m.hint=({documents:'先从名称、地区、期限查起。再看看能交出的技术，以及现场有哪些人。',road:'先比较时间和功能。如果客户只用一个模块，暂缓另一项也可能是好办法。',box:'试着让伙伴能运行和适配，把核心实现留在自己手里。开放更多也可以，但后面要补控制措施。',lab:'负载至少55%，温度不要超过75°C。试试加一组散热，或者适当降低负载。',bargain:'哪一项最缺，就先谈哪一项。人手、现金和自由度，通常要交换条件。'})[m.id];paintMini();break;}case'miniDone':miniComplete();break;case'miniDelegate':miniComplete(true);break;case'endingSkip':document.querySelector('.ending-cinema')?.classList.add('ending-complete');break;case'endingReplay':render();break;}}catch(err){toast(err.message,true);}},true);
document.addEventListener('change',e=>{if(e.target.id==='lab-load'&&miniDraft){miniDraft.load=Number(e.target.value);miniDraft.tested=false;paintMini();}});
document.addEventListener('visibilitychange',()=>{if(document.hidden){motionGame?.loop.sleep();sound.pause();}else{motionGame?.loop.wake();if(started)sound.start();}});
let magnifyLens=null;
document.addEventListener('pointermove',e=>{const clause=e.target.closest?.('.document-clause');if(!miniDraft||miniDraft.id!=='documents'||!clause||e.pointerType==='touch'){magnifyLens?.remove();magnifyLens=null;return;}if(!magnifyLens){magnifyLens=document.createElement('div');magnifyLens.className='magnify-lens';magnifyLens.setAttribute('aria-hidden','true');dialog.append(magnifyLens);}const r=dialog.getBoundingClientRect();magnifyLens.textContent=clause.textContent;magnifyLens.style.left=Math.min(r.width-166,Math.max(6,e.clientX-r.left+16))+'px';magnifyLens.style.top=Math.min(r.height-166,Math.max(6,e.clientY-r.top-140))+'px';});

/* A single nightly inbox and stable explicit decisions. */
let inputRevision=0,inputLockUntil=0,pointerStart=null,nightReportId=null;
function inputBoundary(){inputRevision++;inputLockUntil=performance.now()+220;}
window.addEventListener('pointerdown',e=>{pointerStart={target:e.target.closest('[data-a],[data-v6],[data-v7]'),revision:inputRevision};},true);
window.addEventListener('click',e=>{const b=e.target.closest('[data-a],[data-v6],[data-v7]');if(!b)return;if(e.detail>1||performance.now()<inputLockUntil||(e.detail&&pointerStart&&(pointerStart.target!==b||pointerStart.revision!==inputRevision))){e.preventDefault();e.stopImmediatePropagation();return;}inputLockUntil=performance.now()+160;},true);
function run(action,feedback=true){try{const old=S;clearTimeout(autoTimer);clearTimeout(ackTimer);sceneHold=null;S=E.dispatch(S,action);persist();close();if(S.ending)view='ending';else if(['travel','visit'].includes(action.type)||old.phase!==S.phase)view='scene';if(guide?.task&&(S.completed[guide.task]||action.type==='task'&&action.id===guide.task)||guide?.report&&action.type==='readReport'||guide?.event&&action.type==='readEvent')guide=null;render();const read=['readReport','readEvent','readMessage'].includes(action.type);if(!read){window.scrollTo({top:0});if(feedback)toast(action.type==='sleep'?(S.ending?'本轮结束：'+S.ending.title:'新的一天：'+E.priority(S).label):S.log.at(-1)?.title||'进度已保存。');sound.effect(S.cash>old.cash?'cash':['visit','travel'].includes(action.type)?'door':'confirm');afterAction(old,action);}return true;}catch(e){const box=$('#modal-error');if(dialog.open&&box)box.textContent=e.message;else toast(e.message,true);sound.effect('alert');return false;}}
function afterAction(old,a){if(S.rescuePending){rescuePrompt();return;}if(S.ending||['mini','introSeen'].includes(a.type))return;const job=S.jobs.find(j=>!old.jobs.some(o=>o.id===j.id));if(job)toast((C.people[job.dept]?.name||'团队')+'已接手：D'+job.due+'夜晚汇报。'+(job.status==='queued'?'先准备材料，按排期开展。':'可以到对应地点看团队作业。'));maybePriority();}
function maybePriority(){if(!started||!S||S.ending||dialog.open)return;if(S.rescuePending){rescuePrompt();return;}if(S.phase==='night'&&nightReports().length){report(nightReports()[0].id,true);return;}const next=S.events.find(e=>canEvent(e)&&e.seen!==e.status);if(next){guide=null;if(next.id==='accessrequest'&&next.status==='open')incomingCall(next.id);else eventView(next.id);}}
function countPending(){if(!S||S.ending)return 0;const p=E.priority(S);return S.events.filter(canEvent).length+(p.task&&taskStatus(C.taskById[p.task]).ready?1:0)+(S.offer&&!S.completed.contract&&S.phase==='day'?1:0);}
function nightReports(){return Object.values(S.reports).filter(r=>!r.read).sort((a,b)=>a.day-b.day||a.id.localeCompare(b.id));}
