function capital(){if(S.phase==='night'&&nightReports().length){report(nightReports()[0].id,true);return;}const m=S.market,own=100*m.founder/m.shares;const daily=[...new Map(m.history.map(x=>[x.day,x])).values()].slice(-25),vals=daily.length?daily:[{day:S.day,price:m.price}];const lo=Math.floor(Math.min(...vals.map(x=>x.price))*.94*10)/10,hi=Math.ceil(Math.max(...vals.map(x=>x.price))*1.06*10)/10;const xy=(v,i)=>[65+i*505/Math.max(1,vals.length-1),200-(v.price-lo)/(hi-lo||1)*155];const pts=vals.map((v,i)=>xy(v,i).join(','));const previous=vals.length>1?vals.at(-2).price:10,change=(m.price/previous-1)*100;const locked=S.phase!=='night'?'白天只看行情，夜晚再决定交易':m.lastTrade===S.day?'今晚的1次交易已经用完':'今晚还可以交易1次 · 不耗行动和审批';
 modal('行情与公司资金',`<div class="stock-top"><div><small>华东智行 · 虚构模拟行情</small><h1>¥${m.price.toFixed(2)}</h1><p class="${change>=0?'good':'danger'}">${change>=0?'+':''}${change.toFixed(2)}% · 相比上一经营日</p></div><div><small>公司可用现金</small><h2>${S.cash}万元</h2><small>创始方持股 ${own.toFixed(1)}%</small></div></div><div class="stock-white"><svg viewBox="0 0 640 255" role="img" aria-label="白底股价图，当前每股${m.price.toFixed(2)}元"><rect width="640" height="255" rx="14" fill="white"/>${[0,1,2,3].map(i=>{const value=lo+(hi-lo)*i/3,y=200-i*155/3;return `<path d="M65 ${y}H570" stroke="#dce6e1"/><text x="9" y="${y+5}" fill="#364b43">¥${value.toFixed(1)}</text>`;}).join('')}<polyline fill="none" stroke="#087957" stroke-width="4" stroke-linejoin="round" points="${pts.join(' ')}"/>${vals.map((v,i)=>{const [x,y]=xy(v,i);return `<circle cx="${x}" cy="${y}" r="${i===vals.length-1?6:3}" fill="#087957"><title>D${v.day}: ¥${v.price.toFixed(2)}</title></circle>${i===0||i===vals.length-1||i%5===0?`<text x="${x}" y="229" fill="#364b43" text-anchor="middle">D${v.day}</text>`:''}`;}).join('')}<text x="65" y="20" fill="#364b43">股价 · 元/股</text></svg><div class="stock-range">本局低点 ¥${Math.min(...vals.map(v=>v.price)).toFixed(2)}<b>当前 ¥${m.price.toFixed(2)}</b>本局高点 ¥${Math.max(...vals.map(v=>v.price)).toFixed(2)}</div></div><div class="trade-status">${locked}</div><div class="capital-options">${['issue','buyback'].map(k=>`<section><h3>${k==='issue'?'让出部分股权，融资到账':'花公司现金，回购股份'}</h3>${[10,20,35].map(v=>{const q=X.capitalQuote(S,k,v);return V((k==='issue'?'融资 ':'回购 ')+v+'万元 · 手续费'+q.fee+'万','trade',k+':'+v,'ghost full',q.ok?'':'disabled title="'+esc(q.reason)+'"');}).join('')}</section>`).join('')}</div>${ceo('股价涨跌会改变同样一笔钱能换多少股份。股价高时融资，让出的股份更少；股价低时回购，同样的钱能买回更多。','每天只交易一次。我还得留下能撑到回款的现金。')}<p class="source">只在夜晚正常交易，每晚最多1笔，不占白天行动或夜间审批。股价变动不会直接加减公司现金；成交后才按金额结算。临近停摆时的单次紧急融资另行提示。刷新不会重抽行情。</p><details><summary>行情原因与成交记录</summary>${m.history.slice().reverse().map(x=>`<p>D${x.day} · ¥${x.price.toFixed(2)} · ${esc(x.reason)}</p>`).join('')}${m.trades.map(x=>`<p>D${x.day} · ${x.kind==='issue'?'融资':'回购'}${x.amount}万元 · 成交价¥${x.price} · 现金${x.net>0?'+':''}${x.net}万元</p>`).join('')}</details>`,{kind:'capital',wide:true});}
document.addEventListener('click',e=>{const el=e.target.closest('[data-v7]');if(!el)return;e.preventDefault();e.stopImmediatePropagation();if(el.dataset.v7==='reportNext'){const id=el.dataset.id;if(run({type:'readReport',id},false)){nightReportId=null;if(nightReports().length)report(nightReports()[0].id,true);else company();}}else if(el.dataset.v7==='resumeReports')maybePriority();},true);

function startGuide(target){if(target.phone){phone(target.phone);return;}const t=resolveGuide(target);if(!t)return;guide={...t};close();if(t.report){report(t.report,S.phase==='night'&&!S.reports[t.report]?.read);return;}if(t.event){eventView(t.event);return;}const task=t.task&&C.taskById[t.task],place=task?.place||t.place;guide.place=place;if(S.phase==='night'){company();return;}if(task?.remote){contact(task.person);refreshGuide(true);return;}if(place===S.place){view='scene';render();refreshGuide(true);return;}if(C.places[place]?.city===S.city){placeInfo(place);refreshGuide(true);return;}view='map';render();cityInfo(C.places[place].city);refreshGuide(true);}
function tomorrowCard(){if(S.day>=25)return '<div class="tomorrow-card"><small>本轮最后一晚</small><b>把已完成和未完成的分别交代清楚</b><p>读完到期报告，处理来信，再确认今晚是否交易并完成复盘。</p></div>';const p=E.priority({...S,phase:'day',slots:3});return '<div class="tomorrow-card"><small>明天建议先做</small><b>'+esc(p.label)+'</b><p>'+esc(p.why)+'</p></div>';}

function sceneNext(){const p=E.priority(S);return (p.task&&C.taskById[p.task].place!==S.place||p.place&&p.place!==S.place)?followButton(p,'下一步：'+p.label,'primary full'):'';}

/* V8 work in progress: homepage agenda and a stable daily secretary reminder. */
const agendaV8 = window.HDAgenda;
const v8PreviousGoal = E.goal;
E.goal = function(s) {
  if (s.phase !== 'day' || s.ending) return v8PreviousGoal(s);
  const a = agendaV8.agenda(s);
  return { title: a.title, text: a.summary + ' 剩余' + s.slots + '次行动，可在今日待办中自行安排。',
    ids: a.main?.task && !a.main.settled ? [a.main.task] : [] };
};

function priorityCard() {
  if (S.phase !== 'day') {
    const p = E.priority(S);
    return `<section class="priority-card"><div class="priority-eyebrow">夜间安排</div><h3>${esc(p.label)}</h3><p>${esc(p.why)}</p></section>`;
  }
  const a = agendaV8.agenda(S), m = a.main;
  return `<section class="priority-card daily-critical ${m?.settled ? 'is-done' : ''}">
    <div class="priority-eyebrow">许知微 · 今日关键事项 ${m?.settled ? icon('check') : ''}</div>
    <h3>${esc(m?.settled ? '今天的关键动作已落实' : m?.title || '今天没有新增的关键动作')}</h3>
    <p>${esc(m?.summary || '按已确定的排期推进。')}</p>
    ${m?.actionable && !m.settled ? followButton(m, '查看关键事项', 'primary full') : ''}
    ${a.dueToday.length ? `<p class="agenda-deadline">今天截止 ${a.dueToday.map(e => esc(e.label)).join('、')}</p>` : ''}
  </section>`;
}

function agendaTaskRow(item) {
  const t = C.taskById[item.id];
  const attrs = item.remote || S.place === item.place
    ? `data-a="task" data-id="${esc(item.id)}" data-remote="${item.remote ? '1' : '0'}"`
    : `data-a="follow" data-type="task" data-id="${esc(item.id)}"`;
  const costs = item.cost === item.maxCost ? item.cost : item.cost + '—' + item.maxCost;
  return `<article class="agenda-item ${item.ready ? '' : 'is-blocked'}" data-agenda-id="${esc(item.id)}">
    <div class="agenda-owner">${portrait(item.person, 'small')}<span>${esc(C.people[item.person]?.name || '团队')}<small>${esc(item.access)} · ${esc(item.destination)}</small></span></div>
    <strong>${esc(item.label)}</strong>
    <div class="agenda-cost">预计${costs}万元${item.travelCost ? '＋差旅' + item.travelCost + '万元' : ''}<span>${item.slots}次行动${item.travelCost ? '（含出差）' : ''}</span></div>
    ${item.ready ? `<button class="btn ghost full" ${attrs}>${item.remote || S.place === t.place ? '查看方案' : '查看前往安排'} ${icon('arrow')}</button>` : `<p class="agenda-reason">${esc(item.reason)}</p>`}
  </article>`;
}

function agendaCard() {
  const a = agendaV8.agenda(S);
  return `<section class="today-agenda" aria-labelledby="today-agenda-title">
    <header><div><span>今天由你安排</span><h2 id="today-agenda-title">今日待办</h2></div><b>还剩${S.slots}次行动</b></header>
    <p class="agenda-intro">当前可处理${a.count}项。查看方案免费，确认执行才结算。</p>
    ${a.events.length ? `<div class="agenda-events">${a.events.map(e => `<article class="agenda-event"><small>${e.deadline ? '今天截止' : 'D' + e.due + '前回应'}</small><strong>${esc(e.label)}</strong>${B('查看来信与处置方案', 'event', e.id, 'ghost full')}${e.reason ? '<p>' + esc(e.reason) + '</p>' : ''}</article>`).join('')}</div>` : ''}
    <div class="agenda-ready">${a.ready.map(agendaTaskRow).join('') || '<p class="agenda-empty">当前没有可直接安排的工作。可以查看下方排期与受限原因，再决定如何使用剩余时间。</p>'}</div>
    ${a.blocked.length ? `<details class="agenda-blocked"><summary>暂时受限的事项（${a.blocked.length}）</summary>${a.blocked.map(agendaTaskRow).join('')}</details>` : ''}
    ${a.jobs.length ? `<details class="agenda-jobs"><summary>团队已接手的工作（${a.jobs.length}）</summary>${a.jobs.map(j => `<p><strong>${esc(j.label)}</strong><small>${j.status === 'queued' ? '等待开工' : '执行中'} · D${j.due}夜晚汇报</small></p>`).join('')}</details>` : ''}
  </section>`;
}

const v8PreviousScene = renderScene;
renderScene = function() {
  let html = v8PreviousScene();
  if (S.phase !== 'day' || S.ending) return html;
  const side = `<aside class="rail agenda-rail">${priorityCard()}${agendaCard()}
    <div class="day-end-choice"><p>结束白天会放弃尚未使用的${S.slots}次行动。</p>${B('自行结束今天', 'endDay', '', 'ghost full')}</div></aside></div>`;
  return html.replace(/<aside class="rail">[\s\S]*?<\/aside><\/div>$/, side);
};

function secretary() {
  modal('许知微 · 今日关键事项', `${person('secretary', '我只提醒今天必须留意的关键动作和截止事项。')}${priorityCard()}
    <p class="secretary-boundary">其他工作统一列在首页的今日待办里，由你安排剩余行动。</p>${B('返回现场看待办', 'close', '', 'ghost full')}`,
    { kind: 'secretary', kicker: '阅读不消耗行动' });
}

const v8PreviousControls = controls;
controls = function() {
  return v8PreviousControls().replace('联系秘书许知微，让她带路', '查看许知微的今日关键事项提醒')
    .replace('不知道下一步？', '今日关键事项');
};

function countPending() {
  if (!S || S.ending) return 0;
  if (S.phase !== 'day') return S.events.filter(canEvent).length;
  const a = agendaV8.agenda(S);
  return a.ready.filter(t => t.remote).length + a.events.filter(e => e.ready).length;
}

/* V8 reports and finance. This file is appended inside the existing UI closure. */
const R8=window.HDV8Reports;
let v8BackStack=[],v8Restoring=false,v8FeedbackQueue=null,v8InvestmentDraft=null;
const R8B=(label,action,id='',cls='',more='')=>`<button type="button" class="btn ${cls}" data-a="v8report" data-v8report="${action}" data-id="${esc(id)}" ${more}>${label}</button>`;
const r8Money=x=>R8.money(x),r8Signed=x=>(Number(x)>0?'+':'')+r8Money(x);
function r8Snapshot(){return {nodes:[...dialog.childNodes],className:dialog.className,kind:modalKind,scroll:dialog.querySelector('.dialog-body')?.scrollTop||0,dialogScroll:dialog.scrollTop,choiceDraft,activeTask,remoteTask,draft:Array.isArray(draft)?draft.slice():draft,pending,returnFocus,nightReportId,focus:document.activeElement};}
function r8Restore(){const snap=v8BackStack.pop();if(!snap)return false;v8Restoring=true;inputBoundary();dialog.replaceChildren(...snap.nodes);dialog.className=snap.className;modalKind=snap.kind;choiceDraft=snap.choiceDraft;activeTask=snap.activeTask;remoteTask=snap.remoteTask;draft=snap.draft;pending=snap.pending;returnFocus=snap.returnFocus;nightReportId=snap.nightReportId;if(!dialog.open)dialog.showModal();const body=dialog.querySelector('.dialog-body');if(body)body.scrollTop=snap.scroll;dialog.scrollTop=snap.dialogScroll;snap.focus?.isConnected&&snap.focus.focus({preventScroll:true});v8Restoring=false;return true;}
const r8ModalBefore=modal;
modal=function(title,body,opts={}){
 const parents=['phone','contact','docs','report','nightReports','capital','company','task','event','chairmanAid','reschedule','finalReview'];
 const children=['contact','task','report','topic','knowledge','investmentConfirm','capitalConfirm','confirm','chairmanAid','chairmanConfirm','event','reschedule','rescheduleConfirm','finalUnresolved'];
 if(!v8Restoring&&dialog.open&&parents.includes(modalKind)&&children.includes(opts.kind)&&opts.kind!==modalKind&&!(opts.kind==='report'&&nightReportId))v8BackStack.push(r8Snapshot());
 r8ModalBefore(title,body,opts);
 if(v8BackStack.length&&opts.kind!=='nightReports'){
  const h=dialog.querySelector('.dialog-head');h?.insertAdjacentHTML('afterbegin',R8B('返回','back','','r8-back','aria-label="返回上一页并保留位置"'));
 }
};
const r8CloseBefore=close;
close=function(){v8BackStack=[];r8CloseBefore();};
const r8RunBefore=run;
run=function(action,feedback=true){v8BackStack=[];v8FeedbackQueue=null;return r8RunBefore(action,feedback);};
dialog.addEventListener('cancel',e=>{if(v8BackStack.length){e.preventDefault();e.stopImmediatePropagation();r8Restore();}},true);

function r8Knowledge(reportId){const r=S.reports[reportId];if(!r)return;const cards=R8.knowledge(S,r);modal('这件事对应的知识点',`<div class="r8-knowledge">${cards.length?cards.map(k=>`<section><small>${esc(k.term)}</small><h3>${esc(k.title)}</h3><p>${esc(k.explanation)}</p><p>${esc(k.context)}</p><div class="r8-think"><span>你可以想一想</span><p>${esc(k.question)}</p></div><p class="source">${esc(k.course)} · ${esc(k.assignment)}</p>${k.sources.map(x=>`<a class="r8-source-link" href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${esc(x.title)} · 查看资料</a>`).join('')}</section>`).join(''):'<p>这份报告尚未配置独立的课程主题。可以先对照下方的原始记录。</p>'}<details class="r8-original"><summary>展开完整原始报告与适用范围</summary><p class="source">保留第 ${r.day} 天送达时的记录。后来已补交的材料，以后续报告为准。</p>${(r.lines||[]).map(x=>'<p>'+esc(x)+'</p>').join('')}</details><p class="source">题号依据本次提供的 MIP503 作业。未单独出题的内容标作扩展练习。游戏事件、权利编号和经营数值属于教学模拟。</p>${R8B('看完，回到这份报告','back','','primary full')}</div>`,{kind:'knowledge',wide:true,kicker:'按需要阅读 · 不消耗行动'});sound.effect('paper');}

report=function(id,sequence=false){const r=S.reports[id];if(!r)return;if(!r.read&&S.phase!=='night'){toast('这份新报告今晚汇报。现在可以先看首页的其他待办。');return;}sequence=sequence||!r.read;nightReportId=sequence?id:null;const v=R8.summary(S,r),topics=v.knowledge.map(x=>x.term).slice(0,2).join('、');
 modal(r.title.replace(/报告$/,''),`<article class="r8-report"><div class="night-report-progress">${sequence?'今晚汇报 · 还有 '+nightReports().length+' 份（含本份）':'已经归档的报告'}<span>第 ${r.day} 天送达 · 阅读免费</span></div><div class="r8-report-author">${portrait(C.taskById[id]?.person||'secretary','small')}<span>${esc(C.people[C.taskById[id]?.person||'secretary']?.name||'团队')}<small>把结果说清楚</small></span></div><h3>${esc(v.headline)}</h3>${v.paragraphs.map(x=>'<p>'+esc(x)+'</p>').join('')}${v.range?`<p class="r8-report-range">模拟参考 ${v.range.min}—${v.range.max} 万元，最终金额仍要谈。</p>`:''}${v.next.length?`<div class="r8-report-next"><span>可以接着考虑</span>${v.next.map(id=>`<p>${esc(C.people[C.taskById[id].person].name)}负责的${esc(E.taskLabel(id))}。</p>`).join('')}</div>`:v.event?'<p class="r8-report-next">看完今晚的报告后，可以再打开对应来信决定怎样回应。</p>':''}<button type="button" class="r8-knowledge-link" data-a="v8report" data-v8report="knowledge" data-id="${esc(id)}">这件事对应什么知识点？${topics?' · '+esc(topics):' · 查看原始依据'}</button><div class="night-report-footer">${sequence?`<button class="btn primary full" data-v7="reportNext" data-id="${esc(id)}">${nightReports().length>1?'读完，看下一份':'报告看完了，进入夜间复盘'}</button>`:R8B(v8BackStack.length?'返回上一页':'收起报告','back','','primary full')}</div></article>`,{wide:true,kind:sequence?'nightReports':'report',kicker:'部门汇报'});if(sequence){inputLockUntil=performance.now()+600;dialog.querySelector('[data-a="close"]')?.setAttribute('aria-label','暂时收起，稍后继续这份汇报');}sound.effect('paper');};

function r8FeedbackHTML(row){const m=row.market,p=row.partner;return `<article class="r8-feedback"><div class="r8-feedback-heading"><small>第 ${row.day} 天 · 本次决定</small><h3>${esc(row.label)}</h3></div><section class="r8-partner ${esc(p.tone)}">${portrait('partner','small')}<div><small>新智链的回应${p.delta?' · 合作信任 '+r8Signed(p.delta):''}</small><p>${esc(p.text)}</p></div></section><section class="r8-market"><div><small>客户与市场</small><span class="r8-status">${({none:'暂无新增成交',pending:'等待后续结果',intent:'需求线索',confirmed:'已有确认记录'})[m.status]||'继续跟进'}</span></div><p>${esc(m.text)}</p><div class="r8-sales"><span>决定当天新增项目 <b>${m.orders||0}</b> 个</span><span>决定当天实际回款 <b>${r8Money(m.receipts)}</b> 万元</span>${Number.isFinite(row.cashDelta)?`<span>本次支出 <b>${r8Money(row.expenses)}</b> 万元</span><span>现金净变化 <b>${r8Signed(row.cashDelta)}</b> 万元</span>`:''}</div></section>${row.followups?.length?`<details><summary>这项决定后来的进展</summary>${row.followups.map(x=>`<p>第 ${x.day} 天 · ${esc(x.text)}</p>${x.stage==='completed'?`<p>本次后续确认项目 ${x.orders||0} 个，实际回款 ${r8Money(x.receipts)} 万元。</p>`:''}`).join('')}</details>`:''}</article>`;}
function r8Feedback(row){if(!row||S.ending)return;v8FeedbackQueue=row.id;modal('决定已经传达',`${r8FeedbackHTML(row)}${R8B('收到，继续经营','feedbackDone','','primary full')}`,{wide:true,kind:'decisionFeedback',kicker:'伙伴回应与市场反馈'});sound.effect(row.partner.tone==='concern'?'alert':'message');}
function r8FeedbackArchive(){const rows=(S.v8Feedback||[]).slice().reverse();modal('伙伴与客户的反馈',`<p class="source">按真实提交的决定归档。回看不会再加减指标，也不会重复生成订单。</p>${rows.length?rows.map(r8FeedbackHTML).join(''):'<p>正式签约后，这里会留下每次经营决定的伙伴回应与市场结果。</p>'}${R8B('返回','back','','primary full')}`,{wide:true,kind:'feedbackArchive'});}

function r8MorningHTML(b){const holdings=(b.holdings||b.positions||[]).filter(p=>Number(p.shares??p.quantity)>0),change=Number(b.dayChange)||0;const trades=[...(S.investments?.history||[]).filter(t=>t.day===b.day-1),...(S.market?.trades||[]).filter(t=>t.day===b.day-1&&!String(t.kind).startsWith('investment_'))];return `<div class="r8-morning"><div class="r8-report-author">${portrait('secretary','small')}<span>许知微<small>第 ${b.day} 天 · 早间资金简报</small></span></div>${holdings.length?holdings.map(p=>`<p>公司目前持有 ${esc(p.name)} ${Number(p.shares??p.quantity).toLocaleString('zh-CN')} 股，平均买入成本 ${r8Money(p.avgCost)} 元（含买入费用），最新价 ${r8Money(p.price)} 元。持仓市值 ${r8Money(p.marketValue??p.value)} 万元，当前${Number(p.unrealized)<0?'浮亏':'浮盈'} ${r8Money(Math.abs(Number(p.unrealized)||0))} 万元。</p>`).join(''):'<p>公司目前没有投资持仓，今天没有持仓浮动盈亏。</p>'}<p>今天这次价格更新让持仓市值${change<0?'减少':change>0?'增加':'没有变化'}${change?' '+r8Money(Math.abs(change))+' 万元':''}。已卖出的累计盈亏 ${r8Signed(b.realized)} 万元，早间记录的可动用现金 ${r8Money(b.cash)} 万元。${Number(b.cash)!==Number(S.cash)?'本次查看时现金为 '+r8Money(S.cash)+' 万元，白天已经发生新的收支。':''}</p><p>昨晚${trades.length?'完成了 '+trades.length+' 笔股票操作':'没有股票交易'}。隔夜经营收支让现金变化 ${r8Signed(b.cashChange??(b.cash-b.previousCash))} 万元；交易收付另记在下面的成交记录里。</p><p class="r8-cash-note">持仓涨跌会改变投资市值。买卖成交、交易费用和经营收支才会改变现金，市值没有另算成一笔到账。</p>${trades.length?`<details><summary>昨晚的成交</summary>${trades.map(t=>`<p>${t.kind==='buy'?'买入':t.kind==='sell'?'卖出':t.kind==='issue'?'发行融资':'回购'} ${t.quantity?Number(t.quantity).toLocaleString('zh-CN')+' 股':'一笔'}，现金变化 ${r8Signed(t.cashDelta??t.net)} 万元，费用 ${r8Money(t.fee)} 万元。</p>`).join('')}</details>`:''}</div>`;}
function r8Morning(id){const b=(S.investments?.morningReports||[]).find(x=>x.id===id)||R8.latestMorning(S);if(!b)return;modal('早上好，今天的资金情况到了',`${r8MorningHTML(b)}<div class="toolbar dialog-footer">${R8B('知道了，看看今日待办','morningDone','','primary')}${R8B('查看持仓与行情','capital','','ghost')}</div>`,{wide:true,kind:'morningPortfolio',kicker:'秘书晨报 · 今天提醒一次'});if(!b.acknowledged){try{S=E.dispatch(S,{type:'investment_report_read',id:b.id});persist();}catch(err){toast(err.message,true);}}sound.effect('message');}
const r8PriorityBefore=maybePriority;
maybePriority=function(){if(started&&S&&!S.ending&&!dialog.open&&!S.rescuePending&&S.phase==='day'){const b=R8.latestMorning(S);if(b&&!b.acknowledged){r8Morning(b.id);return;}}r8PriorityBefore();};
const r8AfterBefore=afterAction;
afterAction=function(old,a){if(!S.ending&&!S.rescuePending){const row=(S.v8Feedback||[]).find(x=>!(old.v8Feedback||[]).some(y=>y.id===x.id));if(row){r8Feedback(row);return;}}r8AfterBefore(old,a);};
const r8SecretaryBefore=secretary;
secretary=function(){r8SecretaryBefore();if(!dialog.open)return;const b=R8.latestMorning(S);if(b)dialog.querySelector('.dialog-body')?.insertAdjacentHTML('beforeend',`<div class="r8-secretary-assets"><small>今天的资金事实</small><p>现金 ${r8Money(b.cash)} 万元 · 持仓市值 ${r8Money(b.marketValue)} 万元 · 浮动盈亏 ${r8Signed(b.unrealized)} 万元</p>${R8B('重看今天的持仓简报','morning',b.id,'ghost full')}</div>`);};

function r8Chart(m){const vals=[...new Map((m.history||[]).map(x=>[x.day,x])).values()].slice(-25);if(!vals.length)vals.push({day:S.day,price:m.price});const lo=Math.min(...vals.map(x=>x.price))*.94,hi=Math.max(...vals.map(x=>x.price))*1.06;const xy=(v,i)=>[58+i*522/Math.max(1,vals.length-1),192-(v.price-lo)/(hi-lo||1)*150];return `<div class="r8-stock-chart"><svg viewBox="0 0 640 238" role="img" aria-label="华东智行本局每日股价，当前每股 ${m.price.toFixed(2)} 元"><rect width="640" height="238" rx="16" fill="#fffef8"/>${[0,1,2,3].map(i=>{const val=lo+(hi-lo)*i/3,y=192-i*50;return `<path d="M58 ${y}H580" stroke="#e7e0cd"/><text x="8" y="${y+4}" fill="#5c604f" font-size="12">${val.toFixed(1)}</text>`;}).join('')}<polyline fill="none" stroke="#aa8436" stroke-width="4" stroke-linecap="round" stroke-linejoin="round" points="${vals.map((v,i)=>xy(v,i).join(',')).join(' ')}"/>${vals.map((v,i)=>{const [x,y]=xy(v,i);return `<circle cx="${x}" cy="${y}" r="${i===vals.length-1?5:2.5}" fill="#aa8436"><title>第 ${v.day} 天，${v.price.toFixed(2)} 元</title></circle>${i===0||i===vals.length-1||i%5===0?`<text x="${x}" y="219" text-anchor="middle" fill="#5c604f" font-size="12">D${v.day}</text>`:''}`;}).join('')}</svg></div>`;}
capital=function(tab='portfolio'){
 if(S.phase==='night'&&nightReports().length){report(nightReports()[0].id,true);return;}
 const p=R8.portfolio(S),m=S.market,locked=S.phase!=='night'?'白天查看，今晚再决定是否交易。':m.lastTrade===S.day?'今晚的一次交易已经用过。':'今晚可以操作一次，也可以不交易。';
 const portfolio=`<section class="r8-account"><small>公司投资账户 · 虚构股票</small><h3>持仓与盈亏</h3><div class="r8-finance-stats"><div><small>持仓市值</small><b>${r8Money(p.marketValue)}<em>万元</em></b></div><div><small>浮动盈亏</small><b class="${p.unrealized<0?'r8-loss':'r8-gain'}">${r8Signed(p.unrealized)}<em>万元</em></b></div><div><small>已卖出累计盈亏</small><b>${r8Signed(p.realized)}<em>万元</em></b></div></div>${p.rows.map(x=>`<article class="r8-holding"><div><h4>${esc(x.name)}</h4><span>${Number(x.shares).toLocaleString('zh-CN')} 股 · 买入成本 ${r8Money(x.avgCost)} 元（含费用）</span></div><strong>¥${r8Money(x.price)}</strong><p>目前${x.unrealized<0?'浮亏':'浮盈'} ${r8Money(Math.abs(x.unrealized))} 万元。没有卖出时，这笔涨跌不会直接改变现金。</p></article>`).join('')||'<p>目前没有持仓，可以先了解行情，夜间再决定。</p>'}<label class="field"><span>交易股数 · 每次 100 股起，100 股的整数倍</span><input id="r8-shares" type="number" inputmode="numeric" value="1000" min="100" max="10000" step="100"></label><div class="r8-quote" id="r8-buy-quote"></div><div class="r8-trade-buttons">${R8B('查看买入方案','investmentQuote','buy','primary')}${R8B('查看卖出方案','investmentQuote','sell','ghost')}</div><p class="source">投资与发行融资、回购共用每晚一次机会。可用现金不足或没有足够持股时，不会成交。</p></section>`;
 const issuer=`<section class="r8-account"><small>华东智行 · 公司自己的股权</small><div class="stock-top"><div><h2>¥${m.price.toFixed(2)}</h2><p>每股模拟价格</p></div><div><strong>${(100*m.founder/m.shares).toFixed(1)}%</strong><p>创始方持股</p></div></div>${r8Chart(m)}<div class="capital-options">${['issue','buyback'].map(kind=>`<section><h3>${kind==='issue'?'发行股份，取得融资':'回购股份，使用现金'}</h3>${[10,20,35].map(amount=>{const q=X.capitalQuote(S,kind,amount);return R8B((kind==='issue'?'融资 ':'回购 ')+amount+' 万元','equityQuote',kind+':'+amount,'ghost full',q.ok?'':`disabled title="${esc(q.reason)}"`);}).join('')}</section>`).join('')}</div><p class="source">自己的股份回购用于调整股权，不记作投资收益。股价涨跌会改变同样金额对应的股份数，成交才收付现金。</p></section>`;
 modal('行情与公司资金',`<div class="r8-finance"><div class="r8-cash-header"><span>可以用来付项目费用的现金</span><strong>${r8Money(S.cash)}<small>万元</small></strong></div><div class="r8-capital-tabs">${R8B('投资持仓','capital','portfolio',tab==='portfolio'?'active':'')}${R8B('公司股权与融资','capital','issuer',tab==='issuer'?'active':'')}</div><p class="trade-status">${locked}交易不耗白天行动和夜间审批。</p>${tab==='issuer'?issuer:portfolio}<details class="r8-trade-history"><summary>查看实际成交记录</summary>${(S.investments?.history||[]).slice().reverse().map(t=>`<p>第 ${t.day} 天 · ${t.kind==='buy'?'买入':'卖出'} ${t.quantity} 股，成交价 ${r8Money(t.price)} 元，现金 ${r8Signed(t.cashDelta)} 万元。</p>`).join('')}${(m.trades||[]).filter(t=>!String(t.kind).startsWith('investment_')).slice().reverse().map(t=>`<p>第 ${t.day} 天 · ${t.kind==='issue'?'发行融资':'回购'} ${t.amount} 万元，现金 ${r8Signed(t.net)} 万元。</p>`).join('')||'<p>还没有成交。</p>'}</details><div class="r8-finance-links">${R8.latestMorning(S)?R8B('今天的秘书晨报','morning',R8.latestMorning(S).id,'ghost'):''}${R8B('申请董事长专项支持','chairman','','ghost')}${R8B('伙伴与市场反馈','feedbackArchive','','ghost')}</div></div>`,{wide:true,kind:'capital',kicker:'经营模拟 · 金额与股数分别记录'});r8UpdateQuote();
};
function r8UpdateQuote(){const box=dialog.querySelector('#r8-buy-quote'),input=dialog.querySelector('#r8-shares');if(!box||!input||!X.investmentQuote)return;const quantity=Number(input.value),q=X.investmentQuote(S,'buy','PORT',quantity);box.textContent=q.ok?'按当前价格，买入需要 '+r8Money(Math.abs(q.cashDelta??q.net??q.total??0))+' 万元（含费用）。':q.reason||'请选择股数后查看成交条件。';}
function r8InvestmentQuote(kind){const quantity=Number(dialog.querySelector('#r8-shares')?.value||0),q=X.investmentQuote(S,kind,'PORT',quantity);if(!q.ok){toast(q.reason,true);return;}v8InvestmentDraft={type:'investment',kind,symbol:'PORT',quantity};const cashDelta=q.cashDelta??q.net??(kind==='buy'?-(q.amount+q.fee):q.amount-q.fee);modal(kind==='buy'?'确认买入这些股份？':'确认卖出这些股份？',`<div class="r8-trade-confirm"><p>${kind==='buy'?'买入':'卖出'}海港科技（虚构） ${quantity.toLocaleString('zh-CN')} 股，当前每股 ${r8Money(q.price??S.investments.positions.PORT.price)} 元。</p><p>本次现金变化 ${r8Signed(cashDelta)} 万元，包含交易费用 ${r8Money(q.fee)} 万元。成交后预计可用现金 ${r8Money(S.cash+cashDelta)} 万元。</p><p>这会使用今晚唯一一次交易机会，明天的秘书晨报会记录持仓与最新价格。</p>${R8B('确认'+(kind==='buy'?'买入':'卖出'),'investmentCommit','','primary full')}${R8B('先不交易，返回调整','back','','ghost full')}</div>`,{kind:'investmentConfirm'});}
function r8EquityQuote(value){const [kind,v]=value.split(':'),amount=Number(v),q=X.capitalQuote(S,kind,amount);if(!q.ok){toast(q.reason,true);return;}v8InvestmentDraft={type:'capital',kind,amount};modal('确认这次股权安排？',`<p>${kind==='issue'?'发行股份会引入资金，也会稀释原股东的比例。':'回购会减少外部股份，也会使用公司的现金。'}</p><p>现金变化 ${r8Signed(q.net)} 万元，其中费用 ${r8Money(q.fee)} 万元。创始方持股由 ${q.before}% 变为 ${q.after}%。</p><p>这会使用今晚唯一一次交易机会。</p>${R8B('确认执行','investmentCommit','','primary full')}${R8B('返回调整','back','','ghost full')}`,{kind:'capitalConfirm'});}

function r8Chairman(){const emergency=S.phase==='night'&&S.rescuePending&&S.cash<1;const reports=Object.values(S.reports).filter(r=>r.read),used=!!S.chairmanAid?.used||!!S.v8?.chairmanUsed;modal('申请一次专项支持',`<div class="r8-chairman"><p>把这笔钱用在哪里、眼前缺多少、有什么证据，说清楚后再提交。董事长可能批准、缩减或拒绝。每局只能申请一次。${emergency?'目前召开紧急追加会，不占白天行动或普通夜间审批。':'平时在白天说明用途，使用 1 次行动。'}</p><label class="field"><span>申请金额 · 10 至 25 万元</span><input id="r8-aid-amount" type="number" min="10" max="25" step="1" value="15"></label><label class="field"><span>目前实际需要补的资金 · 万元</span><input id="r8-aid-gap" type="number" min="0.1" max="25" step="0.1" value="10"></label><label class="field"><span>这笔钱的用途</span><select id="r8-aid-purpose"><option value="delivery">完成当前客户交付</option><option value="working">维持必要的项目工作</option>${C.tasks.filter(t=>!S.completed[t.id]&&t.type!=='finish').map(t=>`<option value="${esc(t.id)}">${esc(t.title)}</option>`).join('')}</select></label><label class="field"><span>已经取得的证据</span><select id="r8-aid-evidence"><option value="">选择已有证据</option>${S.contract?'<option value="contract">已签署的客户合作合同</option>':''}${S.flags.delivered?'<option value="milestone">已有阶段交付与到账</option>':''}${reports.map(r=>`<option value="${esc(r.id)}">${esc(r.title)}</option>`).join('')}</select></label><label class="field"><span>为什么现在需要这笔钱</span><textarea id="r8-aid-reason" rows="3" placeholder="请结合现在的项目情况说明，至少 8 个字。"></textarea></label><label class="field"><span>后续怎么回款，或怎么控制继续投入</span><textarea id="r8-aid-exit" rows="3" placeholder="写清下一步的收款或收缩安排，至少 8 个字。"></textarea></label>${R8B('先看申请结果与条件','chairmanQuote','','primary full',used?'disabled':'')}<p class="source">预览不消耗申请次数，正式提交后才记录本次结果。专项支持独立于证券投资，后续使用仍经过现金核对。</p></div>`,{kind:'chairmanAid',wide:true,kicker:'有证据地说明资金需求'});}
function r8ChairmanQuote(){const request={amount:Number($('#r8-aid-amount').value),gap:Number($('#r8-aid-gap').value),purpose:$('#r8-aid-purpose').value,evidence:$('#r8-aid-evidence').value,reason:$('#r8-aid-reason').value.trim(),exitPlan:$('#r8-aid-exit').value.trim()},q=X.chairmanQuote(S,request);if(!q.ok){$('#modal-error').textContent=q.reason;return;}v8InvestmentDraft={type:'chairmanAid',request};modal('这份申请准备好了吗？',`<p>根据当前证据与缺口，这次申请将${q.approved?'获得 '+r8Money(q.approved)+' 万元专项支持':'暂不获批'}。</p><p>${esc(q.reason||'申请金额与现有材料已完成本轮核对。')}</p><p>证据是 ${esc(q.evidenceLabel||request.evidence)}。正式提交使用本局唯一一次申请机会${S.phase==='night'&&S.rescuePending&&S.cash<1?'，本次紧急追加会不另占行动':'和今天 1 次行动'}，结果会写入经营记录。</p>${R8B('确认提交这份申请','investmentCommit','','primary full')}${R8B('返回，继续补充说明','back','','ghost full')}`,{kind:'chairmanConfirm'});}

function r8FinalReview(){
 if(nightReports().length){report(nightReports()[0].id,true);return;}
 const pendingEvents=S.events.filter(e=>['open','report'].includes(e.status)),traded=S.market.lastTrade===S.day||S.tradeSkippedDays?.includes(S.day),p=R8.portfolio(S);
 modal('最后一晚，把这次出海交代清楚',`<div class="r8-final-review"><p>当前可用现金 ${r8Money(S.cash)} 万元，投资持仓市值 ${r8Money(p.marketValue)} 万元，商誉 ${S.goodwill??S.reputation} 分。${S.flags.delivered?'首站已有阶段交付与实际回款。':'首站尚未形成已获接受的阶段交付。'}</p><p>${traded?'今晚已经完成股票操作或明确选择不交易。':'今晚还没有股票操作。你可以先查看行情，也可以明确选择今晚不交易。'}</p>${pendingEvents.length?`<div class="r8-report-next"><span>这几件事还需要你回应</span>${pendingEvents.map(e=>B(C.eventById[e.id]?.title||'待回应事项','event',e.id,'ghost full')).join('')}</div>${S.nightUsed?R8B('本轮行动已用完，查看未处理事项的后果','finalUnresolvedQuote','','ghost full'):''}<p>先处理这些仍待决定的事项，再完成最后复盘。已经交给团队的工作按实际状态结算，不提前当作完成。</p>`:`<p>当前没有尚未回应的来信。完成复盘后，将按已经发生的决定、交付与收支进入本轮结局。</p>${!S.flags.delivered?'<label class="choice-check"><input type="checkbox" id="r8-withdraw"><span>主动止损，按现有记录收回团队与资料。未决义务仍需交代。</span></label>':''}${R8B(traded?'完成今晚复盘，查看结果':'今晚不交易，完成复盘','finalCommit','','primary full')}`}${R8B('先查看今晚的行情','capital','','ghost full')}${R8B('先收起，继续检查','back','','ghost full')}</div>`,{kind:'finalReview',wide:true,kicker:'第 25 天 · 夜间复盘'});
}
function r8FinalUnresolvedQuote(){let next;try{next=E.dispatch(S,{type:'finalizeUnresolved'});}catch(err){toast(err.message,true);return;}const rows=S.events.filter(e=>['open','report'].includes(e.status)),delta=Number(next.reputation)-Number(S.reputation),notes=next.log.slice(S.log.length).filter(x=>x.text);v8InvestmentDraft={type:'finalizeUnresolved'};modal('确认登记这些未处理事项？',`<p>本轮已经没有可用审批。以下 ${rows.length} 件事会按未处理登记，相关承诺仍保留在复盘里，不会自动变成已解决。</p><div class="r8-report-next">${rows.map(e=>'<p>'+esc(C.eventById[e.id]?.title||e.id)+'</p>').join('')}</div><p>按当前事件规则，商誉变化 ${r8Signed(delta)} 分，登记后为 ${next.reputation} 分。${next.ending?'这次后果将触发本轮海外扩张结束。':'之后还要看完产生的报告，完成交易或明确不交易，再做最后复盘。'}</p>${notes.length?'<details><summary>逐项查看结算原因</summary>'+notes.map(x=>'<p>'+esc(x.text)+'</p>').join('')+'</details>':''}${R8B('确认登记未处理事项并结算后果','investmentCommit','','danger full')}${R8B('返回，再看一次原事项','back','','ghost full')}`,{kind:'finalUnresolved',wide:true,kicker:'只结算已经说明的后果'});}
function r8FinishReview(){const withdrawal=!!dialog.querySelector('#r8-withdraw')?.checked;if(S.events.some(e=>['open','report'].includes(e.status))){r8FinalReview();return;}if(S.market.lastTrade!==S.day&&!S.tradeSkippedDays?.includes(S.day)){if(!run({type:'skipTrade'},false))return;}if(!S.nightReviewedDays?.includes(S.day)){if(!run({type:'nightReview',withdrawal},false))return;}run({type:'sleep'});}
const r8ClickBefore=clickAction;
clickAction=async function(el){if(el.dataset.a==='close'&&v8BackStack.length){r8Restore();return;}if(el.dataset.a==='sleep'&&S?.version>=8&&S.day===25&&S.phase==='night'){r8FinalReview();return;}if(['stopAsk','stop'].includes(el.dataset.a)&&S?.version>=8){r8Chairman();return;}return r8ClickBefore(el);};
const r8RescueBefore=rescuePrompt;
rescuePrompt=function(){if(S?.version<8)return r8RescueBefore();const options=S.rescueOptions||{},canIssue=[35,20,10].some(v=>X.capitalQuote(S,'issue',v,true).ok),canAid=!S.chairmanAid?.used&&(!!S.contract||S.flags.delivered||Object.values(S.reports).some(r=>r.read));modal('项目资金需要你决定',`<div class="r8-rescue"><p>本次海外项目的可用现金还剩 ${r8Money(S.cash)} 万元，已经不足以继续正常支出。国内公司的资产没有自动转入这个项目。</p>${canIssue?`<p>当前还有符合条件的紧急融资选项，会计入本轮融资上限。</p>${R8B('接受本次可用的紧急融资','rescueIssue','','primary full')}`:''}${canAid?`<p>你也可以用已取得的报告、合同或交付结果，申请本局仅一次的专项支持。当前现金不足时，可以直接召开紧急追加会。</p>${R8B('整理证据，申请专项支持','chairman','','primary full')}`:''}${options.waitForNight&&S.phase==='day'?'<p>股票操作留到夜晚。目前仍有当晚可以评估的融资额度，可以先结束白天再安排。</p>'+R8B('结束白天，今晚再安排融资','rescueWaitNight','','primary full'):''}${!canIssue&&!canAid&&!options.waitForNight?'<p>当前没有可用融资或可提交的专项支持证据。</p>':''}${nightReports().length?R8B('先听完团队报告','resumeReports','','ghost full'):''}${R8B('放弃本次援助，结束海外项目','rescueDecline','','ghost full')}</div>`,{kind:'rescue',wide:true,kicker:'海外项目资金 · 等待你的确认'});};

const r8PhoneBefore=phone;
phone=function(tab='messages'){r8PhoneBefore(tab);dialog.querySelector('.dialog-body')?.insertAdjacentHTML('beforeend',`<div class="r8-phone-links">${R8B('伙伴与市场反馈','feedbackArchive','','ghost full')}${R8.latestMorning(S)?R8B('今天的持仓简报','morning',R8.latestMorning(S).id,'ghost full'):''}</div>`);};
const r8JobsBefore=jobsHTML;
jobsHTML=function(){return r8JobsBefore().replace(/(<button\b[^>]*data-a="cancelJobAsk"\s+data-id="([^"]+)"[^>]*>[\s\S]*?<\/button>)/g,(button,_,id)=>S.jobs.some(j=>j.id===id&&j.status==='queued')?`<div class="r8-job-actions">${R8B('调整开始日期','reschedule',id,'ghost')}${button}</div>`:button);};
function r8Reschedule(id){const j=S.jobs.find(j=>j.id===id&&j.status==='queued');if(!j){toast('这项工作已开工或结束，不能再改开始日期。',true);return;}const running=S.jobs.find(x=>x.dept===j.dept&&x.status==='running'),earliest=Math.max(S.day,running?.due||S.day),latest=25-(j.due-j.start),eventId=j.data?.v8Event||j.data?.event||j.data?.business||j.data?.drama,title=C.taskById[j.task]?.title||C.eventById[eventId]?.title||'排队工作';modal('调整这项工作的开始日期',`<div class="r8-reschedule"><h3>${esc(title)}</h3><p>这项工作还没有开工，目前安排在第 ${j.start} 天开始，第 ${j.due} 天交回结果。${running?'同部门前一项工作预计第 '+running.due+' 天完成。':'同部门目前没有其他正在执行的工作。'}</p><label class="field"><span>希望从第几天开始</span><input id="r8-job-start" type="number" inputmode="numeric" min="${earliest}" max="${Math.max(earliest,latest)}" step="1" value="${Math.min(Math.max(earliest,j.start),Math.max(earliest,latest))}"></label><p class="source">改排期不重复收取已经支付的准备费用。事件的后续核对还要有本轮可用日期，预览会按实际排期检查。</p>${R8B('检查新日期和预计结果','rescheduleQuote',id,'primary full')}${R8B('保留原排期，返回','back','','ghost full')}</div>`,{kind:'reschedule',wide:true,kicker:'尚未开工 · 调整前先看影响'});}
function r8RescheduleQuote(id){const start=Number(dialog.querySelector('#r8-job-start')?.value),action={type:'rescheduleJob',id,start};let next;try{next=E.dispatch(S,action);if(next.actions.length===S.actions.length)throw Error(next.rescuePending?'先处理当前资金问题，再调整工作排期。':'当前状态没有接受这次调整。');}catch(err){const box=dialog.querySelector('#modal-error');if(box)box.textContent=err.message;return;}const j=next.jobs.find(j=>j.id===id),eventId=j.data?.v8Event||j.data?.event||j.data?.business||j.data?.drama,ev=next.events.find(e=>e.id===eventId);v8InvestmentDraft=action;modal('确认按新日期安排？',`<p>改为第 ${j.start} 天开始，第 ${j.due} 天交回工作结果。${ev?.followupDay?'这件事的后续核对安排在第 '+ev.followupDay+' 天。':''}</p><p>这次现金变化 ${r8Signed(next.cash-S.cash)} 万元。前期已经发生的费用不再次收取，后续结果仍要按实际完成情况查看。</p>${R8B('确认调整排期','investmentCommit','','primary full')}${R8B('返回修改日期','back','','ghost full')}`,{kind:'rescheduleConfirm'});}
document.addEventListener('click',e=>{
 const el=e.target.closest('[data-v8report]');if(!el||el.disabled)return;e.preventDefault();e.stopImmediatePropagation();const action=el.dataset.v8report,id=el.dataset.id||'';sound.start();
 try{switch(action){
 case'back':if(!r8Restore()){v8BackStack=[];r8CloseBefore();}break;
 case'knowledge':r8Knowledge(id);break;
 case'capital':capital(id||'portfolio');break;
 case'feedbackArchive':r8FeedbackArchive();break;
 case'feedbackDone':v8FeedbackQueue=null;v8BackStack=[];r8CloseBefore();maybePriority();break;
 case'morning':r8Morning(id);break;
 case'morningDone':v8BackStack=[];r8CloseBefore();maybePriority();break;
 case'investmentQuote':r8InvestmentQuote(id);break;
 case'equityQuote':r8EquityQuote(id);break;
 case'investmentCommit':{const a=v8InvestmentDraft;if(a){v8InvestmentDraft=null;if(!run(a))v8InvestmentDraft=a;}break;}
 case'chairman':r8Chairman();break;
 case'chairmanQuote':r8ChairmanQuote();break;
 case'finalCommit':r8FinishReview();break;
 case'finalUnresolvedQuote':r8FinalUnresolvedQuote();break;
 case'rescueIssue':run({type:'rescue',accept:true});break;
 case'rescueWaitNight':run({type:'endDay'});break;
 case'rescueDecline':v8InvestmentDraft={type:'rescue',accept:false};modal('确定放弃本次资金援助？',`<p>确认后将按当前经营记录结束本轮海外项目。</p>${R8B('确认放弃，结束本轮','investmentCommit','','danger full')}${R8B('返回查看援助条件','rescueBack','','primary full')}`,{kind:'rescueConfirm'});break;
 case'rescueBack':rescuePrompt();break;
 case'resumeReports':if(nightReports().length)report(nightReports()[0].id,true);break;
 case'reschedule':r8Reschedule(id);break;
 case'rescheduleQuote':r8RescheduleQuote(id);break;
 }}catch(err){const box=dialog.querySelector('#modal-error');if(box)box.textContent=err.message;else toast(err.message,true);}
},true);
document.addEventListener('input',e=>{if(e.target.id==='r8-shares')r8UpdateQuote();});

