const M8=window.HDMiniV8Model;
Object.keys(M8.titles).forEach(id=>{MINI[id]=[M8.titles[id],'亲手试一遍，再决定正式安排。'];});
let m8Remembered=null,m8FlipTimer=null,m8Gesture=null,m8IgnoreClick=false;
const m8Button=(label,action,id='',cl='',disabled=false)=>`<button type="button" class="m8-button ${cl}" data-m8="${action}" data-id="${esc(id)}" data-m8-key="${esc(action+'-'+id)}" ${disabled?'disabled':''}>${label}</button>`;
function m8Init(id){const common={id,hint:'',hintLevel:0};if(id==='documents')return {...common,found:[],selectedLine:null,activeDoc:0};if(id==='road')return {...common,moves:[],selected:null,flash:[],...M8.matchSession(S.seed)};if(id==='lab')return {...common,turns:M8.wireInitial(S.seed),tested:false};if(id==='box')return {...common,moves:[],selected:'api',...M8.slideSession()};return {...common,cards:M8.memoryCards(S),claims:M8.evidenceClaims(S),flipped:[],matches:[],busy:false};}
openMini=function(id,next=null){if(!X.miniAvailable(S,id)){toast('这项互动已经完成，或还没有相关材料。');return;}clearTimeout(m8FlipTimer);miniNext=next;miniDraft=m8Remembered?.id===id&&m8Remembered.seed===S.seed&&m8Remembered.day===S.day?m8Remembered.draft:m8Init(id);miniDraft.busy=false;if(miniDraft.id==='bargain')miniDraft.flipped=[];paintMini();};
function m8DocHTML(m){return `<div class="m8-document-toolbar"><span>已标记 <b>${m.found.length}/5</b> 类疑点</span><span>镜片 <b>1.9倍</b> · 拖动镜柄或点文字</span></div><p class="m8-instruction">先点一处文字，再点与它不一致的另一处。对照后会贴上待核验便签。错点不扣钱。</p><div class="m8-doc-tabs" role="tablist" aria-label="三份文件">${M8.docs.map((d,i)=>m8Button(`${i+1} ${d.title}`,'docTab',i,i===m.activeDoc?'selected':'')).join('')}</div><div class="m8-papers">${M8.docs.map((d,i)=>`<article class="m8-paper ${i===m.activeDoc?'active':''}" data-doc="${i}" aria-label="${d.title}"><div class="m8-paper-print"><small>${d.number}</small><h3>${d.title}</h3>${d.lines.map(([label,text,clue],j)=>`<button type="button" class="m8-doc-line ${m.found.includes(clue)?'found':''} ${m.selectedLine===i+':'+j?'selected':''}" data-m8="clause" data-id="${i}:${j}" data-m8-key="clause-${i}:${j}"><small>${label}</small><span>${esc(text)}</span>${m.found.includes(clue)?'<em>待核验 · '+M8.clues[clue][0]+'</em>':''}</button>`).join('')}<div class="m8-paper-sign">供本次模拟核验</div></div></article>`).join('')}</div><div class="m8-mirror-tools">${m8Button('⌕ 拖动这里移动镜片','lensHandle','','m8-lens-handle')}${m8Button('收起镜片','lensHide','','quiet')}</div><div class="m8-note-rack">${M8.clues.map((c,i)=>`<span class="${m.found.includes(i)?'found':''}">${m.found.includes(i)?'已圈出 '+c[0]:'便签 '+(i+1)+' · 待发现'}</span>`).join('')}</div>`;}
const M8_FILES=[['合','合同'],['权','授权'],['测','测试'],['账','付款'],['人','人员']];
function m8MatchHTML(m){return `<div class="m8-puzzle-layout"><div class="m8-match-panel"><div class="m8-game-hud"><span>剩余 <b>${m.left}</b> 步</span><span>入柜 <b>${m.cleared}/30</b></span><span>四连协作 <b>${m.bonus}</b></span></div><div class="m8-match-grid" role="group" aria-label="6乘6资料棋盘">${m.board.map((v,i)=>m8Button(`<span class="m8-folder-tab"></span><b>${M8_FILES[v][0]}</b><small>${M8_FILES[v][1]}</small>`,'tile',i,`m8-file file-${v} ${m.selected===i?'selected':''} ${m.flash?.includes(i)?'just-cleared':''}`,m.finished)).join('')}</div><div class="m8-file-cabinet"><span>资料归档柜</span><i style="--fill:${Math.min(100,m.cleared/30*100)}%"></i><b>${m.finished?'本轮整理结束':'文件等待归柜'}</b></div></div><aside class="m8-puzzle-side"><h3>先选一份，再点旁边一份</h3><p>交换相邻文件，连成三个就会入柜。四连能带动协作。一轮12步，试着把至少30份资料归档。</p><p>没有形成三连的交换会退回，不扣步数。没有可用交换时，文件自动重排，不扣钱。</p><p class="m8-small">只影响整理效率，最多节省1万元行政支出。专利、授权和交付问题还要另外处理。</p>${m.shuffles?`<p role="status">已自动重排${m.shuffles}次。</p>`:''}${m.finished?'<div class="m8-result-good">文件已归柜，可以记录结果。</div>':''}</aside></div>`;}
function m8WireSVG(mask,lit){return `<svg viewBox="0 0 80 80" aria-hidden="true"><rect x="4" y="4" width="72" height="72" rx="12" class="m8-wire-base"/>${[[1,'40,0 40,40'],[2,'80,40 40,40'],[4,'40,80 40,40'],[8,'0,40 40,40']].filter(([b])=>mask&b).map(([b,p])=>`<polyline points="${p}" class="m8-wire-shadow"/><polyline points="${p}" class="m8-wire-path ${lit?'live':''}"/>`).join('')}<circle cx="40" cy="40" r="8" class="m8-wire-node ${lit?'live':''}"/></svg>`;}
function m8WireHTML(m){const w=M8.wireState(m.turns),on=m.tested&&w.connected;return `<div class="m8-puzzle-layout"><div class="m8-wiring-machine ${on?'connected':''}"><div class="m8-game-hud"><span>试验负载 <b>70%</b></span><span>温度 <b>${m.tested?w.heat+'°C':'待测试'}</b></span></div><div class="m8-wiring-shell"><span class="m8-wire-input">电源</span><div class="m8-wire-grid" role="group" aria-label="旋转接线模块">${w.masks.map((mask,i)=>m8Button(m8WireSVG(mask,m.tested&&w.lit.includes(i))+'<span class="m8-sr">第'+(Math.floor(i/4)+1)+'行第'+(i%4+1)+'列，接口'+[[1,'上'],[2,'右'],[4,'下'],[8,'左']].filter(([bit])=>mask&bit).map(x=>x[1]).join('、')+'；点击旋转</span>','wire',i,'m8-wire-cell')).join('')}</div><span class="m8-wire-output">风扇</span></div><div class="m8-device-feedback"><div class="m8-fan ${on?'spinning':''}" aria-hidden="true"><i></i><i></i><i></i></div><div><strong>${!m.tested?'等待试运行':on?'散热风扇已启动':'接线未连通'}</strong><span>${!m.tested?'模块旋转后再测一次':on?'模拟温度回到58°C':'模拟温度96°C，继续检查断点'}</span></div><div class="m8-thermometer"><i style="height:${m.tested?Math.min(100,w.heat):0}%"></i></div></div>${m8Button('通电测试','wireTest','','primary wide')}</div><aside class="m8-puzzle-side"><h3>让电流接到右侧风扇</h3><p>点一个模块，顺时针转90度。把左侧第二行的电源，接到右侧第三行的风扇。</p><p>通电后，真正相连的线路会亮起。风扇启动后，温度会下降。改动任何模块都需要重新测试。</p><p class="m8-small">这是方案模拟。以前发现的专利障碍仍需单独决定许可、绕行或缩减功能。</p></aside></div>`;}
function m8SlideHTML(m){const b=M8.slideSession(m.moves),selected=b.blocks.find(x=>x.id===m.selected);return `<div class="m8-puzzle-layout"><div><div class="m8-game-hud"><span>移动 <b>${m.moves.length}</b> 次</span><span>核心区 <b>已锁定</b></span></div><div class="m8-vault-shell"><div class="m8-vault-grid" role="group" aria-label="移动权限隔板">${b.blocks.map(p=>`<button type="button" class="m8-vault-block block-${p.id} ${p.fixed?'fixed':''} ${p.id===m.selected?'selected':''}" style="--x:${p.x};--y:${p.y};--w:${p.w};--h:${p.h}" data-m8="block" data-id="${p.id}" data-m8-key="block-${p.id}" aria-label="${p.label}${p.fixed?'，保持锁定':p.axis==='x'?'，可左右移动':'，可上下移动'}" ${p.fixed?'disabled':''}><b>${p.fixed?'▣ ':''}${p.label}</b><small>${p.fixed?'留在公司':p.id==='api'?'送往窗口':p.axis==='x'?'左右移动':'上下移动'}</small></button>`).join('')}</div><span class="m8-vault-exit ${b.finished?'open':''}">合作<br>窗口</span></div><div class="m8-slide-controls"><strong>当前选中 ${esc(selected?.label||'接口')}</strong>${m8Button(selected?.axis==='y'?'上移一格':'左移一格','slide',-1,'',!selected||!M8.canSlide(b.blocks,m.selected,-1))}${m8Button(selected?.axis==='y'?'下移一格':'右移一格','slide',1,'',!selected||!M8.canSlide(b.blocks,m.selected,1))}${m8Button('撤回一步','undo','','quiet',!m.moves.length)}</div>${b.finished?'<div class="m8-result-good">接口已到合作窗口，核心区仍在公司。</div>':''}</div><aside class="m8-puzzle-side"><h3>把接口送出去，把核心留住</h3><p>先点一块权限隔板，再用下方按钮移动。也可以沿隔板方向拖动，每次移动一格。</p><p>人员、使用范围、日志和期限挡在通道上。把位置理顺，给接口留下通路。核心区不能移动。</p><p class="m8-small">这里形成权限草案。继续经营时还要确认正式许可范围，移动隔板不等于签约授权。</p></aside></div>`;}
function m8MemoryHTML(m){const matched=new Set(m.matches.map(p=>p.claimId)),missing=m.claims.filter(c=>!c.record);return `<div class="m8-evidence-meeting">${person('market','客户愿意听，但我们拿出来的每份材料都要有出处。','small')}<div class="m8-game-hud"><span>已有记录 <b>${m.matches.length}/${m.claims.length-missing.length}</b></span><span>材料待补 <b>${missing.length}</b></span></div><p class="m8-instruction">翻开两张，把客户的问题与本局已取得、已阅读的记录配对。没有材料的问题，留在下方待补。</p><div class="m8-memory-grid">${m.cards.map((c,i)=>{const open=m.flipped.includes(i)||matched.has(c.claimId);return m8Button(`<span class="m8-memory-back" aria-hidden="${open?'true':'false'}"><small>${String(i+1).padStart(2,'0')}</small><b>${c.type==='claim'?'客户问什么':'我们有什么'}</b><span>点击翻开</span></span><span class="m8-memory-front" aria-hidden="${open?'false':'true'}"><small>${c.type==='claim'?'客户问题':'本局记录 · 第'+c.record.day+'天'}</small><b>${esc(c.text)}</b>${c.record?'<span>档案 '+esc(c.record.id)+'</span>':''}${matched.has(c.claimId)?'<em>已钉上证据板</em>':''}</span>`,'card',i,`m8-memory-card ${open?'flipped':''} ${matched.has(c.claimId)?'matched':''}`,m.busy||matched.has(c.claimId));}).join('')}</div><div class="m8-evidence-board"><h3>可以拿出这些材料</h3>${m.matches.length?m.matches.map(p=>{const c=m.claims.find(x=>x.id===p.claimId);return `<article><b>${esc(c.statement)}</b><p>${esc(c.limit)}</p><small>来源 ${esc(c.record.id)} · ${esc(c.record.title)}</small></article>`;}).join(''):'<p>配对成功的记录会钉在这里。</p>'}</div>${missing.length?`<div class="m8-missing-evidence"><h3>没有材料，暂不下结论</h3>${missing.map(c=>`<p><b>待补</b> ${esc(c.question)}</p>`).join('')}</div>`:''}<div class="m8-reporter-reaction" role="status">${m.matches.length?'记者点了点材料上的日期：“这些记录可以核对。剩下的问题，我们等补充信息。”':m.cards.length?'记者翻开笔记，等你拿出能核对的材料。':'目前没有可出示的已读报告。说明材料待补，不编造记录。'}</div></div>`;}
paintMini=function(){const m=miniDraft;if(!m)return;m8Remembered={seed:S.seed,day:S.day,id:m.id,draft:m};const previous=document.activeElement?.dataset?.m8Key,scroll=dialog.querySelector('.dialog-body')?.scrollTop||0;const valid=m.id==='documents'?m.found.length===5:m.id==='road'?m.finished:m.id==='lab'?m.tested:m.id==='box'?M8.slideSession(m.moves).finished:m.matches.length===m.claims.filter(c=>c.record).length;const body=({documents:m8DocHTML,road:m8MatchHTML,lab:m8WireHTML,box:m8SlideHTML,bargain:m8MemoryHTML})[m.id](m);modal(M8.titles[m.id],`<div class="m8-root" data-game="${m.id}">${body}<div class="m8-secretary-note" role="status">${m.hint?esc(m.hint):'这项互动不另外扣行动。你可以自己试，也可以请团队接手。'}</div><div class="m8-footer">${m8Button('给我一个提示','hint','','quiet')}${m8Button('团队接手 · 1万元','delegate','','quiet',S.cash<1)}${m8Button('暂不整理 · 无收益','skip','','quiet')}${m8Button(m.id==='bargain'?'按现有材料回应':'记录结果，继续经营','done','','primary',!valid||m.busy)}</div><p class="m8-small">每类互动本局只结算一次。关掉窗口可稍后继续；重做不重复领收益。</p></div>`,{wide:true,kind:'mini',kicker:'现场互动 · '+M8.titles[m.id]});miniDraft=m;dialog.classList.add('m8-dialog');dialog.querySelector('.dialog-body').scrollTop=scroll;if(previous)dialog.querySelector('[data-m8-key="'+CSS.escape(previous)+'"]')?.focus({preventScroll:true});};
miniComplete=function(delegated=false,skipped=false){const m=miniDraft;if(!m||m.busy)return;const next=miniNext;let payload=delegated?{delegated:true}:skipped?{skipped:true}:m.id==='documents'?{found:m.found}:m.id==='road'||m.id==='box'?{moves:m.moves}:m.id==='lab'?{turns:m.turns,tested:m.tested}:{matches:m.matches,unanswered:m.claims.filter(c=>!c.record).map(c=>c.id)};if(run({type:'mini',id:m.id,payload},false)){clearTimeout(m8FlipTimer);m8Remembered=null;miniNext=null;toast(S.minis[m.id].detail);if(next&&!S.ending)setTimeout(next,250);}};
function m8Hint(m){m.hintLevel++;if(m.id==='documents'){const c=M8.clues.find((x,i)=>!m.found.includes(i));m.hint=c?(m.hintLevel>2?c[2]:c[1]):'五类疑点都找到了，交给法务核实即可。';}else if(m.id==='road'){const move=M8.legalSwaps(m.board)[0];m.hint=move?'试试把第'+(Math.floor(move.a/6)+1)+'行第'+(move.a%6+1)+'列，和第'+(Math.floor(move.b/6)+1)+'行第'+(move.b%6+1)+'列互换。':'本轮可以记录结果了。';m.selected=move?.a??null;}else if(m.id==='lab'){m.hint=m.hintLevel<2?'先让左侧第二行电源的接口朝左右。点通电测试，沿着亮线找第一个断点。':'一条可行路线经过第二行第1、2格，再上到第一行第2、3格，沿第三列下到第三行，最后向右到风扇。';}else if(m.id==='box'){m.hint=m.hintLevel<2?'先把底部的日志隔板向左移开。为人员和范围隔板留出向下的空位。':'日志向左两格，人员向下两格，范围向下三格，最后把接口向右送到窗口。';}else m.hint='问题与记录要能对应。专利调查只能说明调查过的范围；权限报告不能替代现场验收记录。缺少材料就留空。';paintMini();}
function m8SelectTile(i){const m=miniDraft;if(!m||m.id!=='road'||m.finished)return;if(m.selected===null){m.selected=i;paintMini();return;}const a=m.selected;m.selected=null;if(a===i){paintMini();return;}if(!M8.adjacent(a,i)){m.selected=i;m.hint='先选一份资料，再点它上下左右相邻的一份。';paintMini();return;}try{const result=M8.matchSession(S.seed,[...m.moves,{a,b:i}]);Object.assign(m,result);m.flash=result.last;m.hint=result.finished?'本轮整理完成，资料已进入档案柜。':'文件已入柜，新资料补上了空位。';sound.effect('paper');paintMini();const current=m;setTimeout(()=>{if(miniDraft===current&&modalKind==='mini'){current.flash=[];dialog.querySelectorAll('.just-cleared').forEach(n=>n.classList.remove('just-cleared'));}},340);}catch(err){m.hint=err.message;paintMini();}}
function m8Slide(dir){const m=miniDraft;if(!m||m.id!=='box')return;const b=M8.slideSession(m.moves);if(!M8.canSlide(b.blocks,m.selected,dir)){m.hint='前面没有空位。先移动其他隔板，也可以撤回上一步。';paintMini();return;}m.moves.push({id:m.selected,dir});m.hint='隔板已移开一格。核心区保持锁定。';sound.effect('paper');paintMini();}
function m8Flip(i){const m=miniDraft;if(!m||m.id!=='bargain'||m.busy||m.flipped.includes(i)||m.matches.some(p=>p.claimId===m.cards[i]?.claimId))return;m.flipped.push(i);sound.effect('paper');if(m.flipped.length<2){paintMini();return;}const [a,b]=m.flipped.map(x=>m.cards[x]);if(a.type!==b.type&&a.claimId===b.claimId){const record=a.type==='record'?a:b;m.matches.push({claimId:record.claimId,recordId:record.id});m.flipped=[];m.hint='这份记录能支持对应范围的说明。材料已经钉上证据板。';paintMini();return;}m.busy=true;m.hint='这两张还不能配在一起。先记住位置，再找对应的材料。';paintMini();m8FlipTimer=setTimeout(()=>{if(miniDraft!==m||modalKind!=='mini')return;m.flipped=[];m.busy=false;paintMini();},1050);}
function m8LensAt(clientX,clientY,source){if(!miniDraft||miniDraft.id!=='documents'||modalKind!=='mini')return;const paper=source?.closest?.('.m8-paper')||[...dialog.querySelectorAll('.m8-paper')].find(p=>{const r=p.getBoundingClientRect();return clientX>=r.left&&clientX<=r.right&&clientY>=r.top&&clientY<=r.bottom;});if(!paper)return;const print=paper.querySelector('.m8-paper-print'),r=print.getBoundingClientRect();let lens=dialog.querySelector('.m8-lens');if(!lens){lens=document.createElement('div');lens.className='m8-lens';lens.setAttribute('aria-hidden','true');dialog.append(lens);}const size=156,zoom=1.9,left=Math.max(6,Math.min(window.innerWidth-size-6,clientX-size/2)),top=Math.max(8,clientY-size-34);lens.style.left=left+'px';lens.style.top=top+'px';lens.innerHTML='<div class="m8-lens-print">'+print.innerHTML+'</div>';const content=lens.firstElementChild;content.style.width=r.width+'px';content.style.left=((size-14)/2-(clientX-r.left)*zoom)+'px';content.style.top=((size-14)/2-(clientY-r.top)*zoom)+'px';content.style.transform='scale('+zoom+')';lens.querySelectorAll('button').forEach(b=>{b.tabIndex=-1;b.removeAttribute('data-m8');});}
document.addEventListener('click',e=>{const el=e.target.closest?.('[data-m8]');if(!el||el.disabled||!miniDraft||modalKind!=='mini')return;e.preventDefault();e.stopImmediatePropagation();if(m8IgnoreClick){m8IgnoreClick=false;return;}const action=el.dataset.m8,id=el.dataset.id,m=miniDraft;try{sound.start();switch(action){case'docTab':m.activeDoc=Number(id);paintMini();break;case'clause':{const [d,l]=id.split(':').map(Number),line=M8.docs[d].lines[l],clue=line[2];if(clue===undefined){m.hint='这一项暂未看到两份材料冲突。继续核对主体、地区和具体承诺。';paintMini();break;}if(m.found.includes(clue)){m.hint=M8.clues[clue][2];paintMini();break;}const first=m.selectedLine?.split(':').map(Number),previous=first?M8.docs[first[0]].lines[first[1]]:null;if(m.selectedLine!==id&&previous?.[2]===clue){m.found.push(clue);m.selectedLine=null;m.hint=M8.clues[clue][2];sound.effect('paper');}else{m.selectedLine=id;m.hint='这一处记下了。再点另一处与它不一致的文字，放在一起比较。';}paintMini();const again=dialog.querySelector('[data-m8-key="clause-'+CSS.escape(id)+'"]');if(again){const r=again.getBoundingClientRect();m8LensAt(e.clientX||r.left+r.width/2,e.clientY||r.top+r.height/2,again);}break;}case'lensHandle':{const paper=dialog.querySelector('.m8-paper.active')||dialog.querySelector('.m8-paper');const r=paper?.getBoundingClientRect();if(r)m8LensAt(r.left+r.width/2,r.top+Math.min(170,r.height/2),paper);break;}case'lensHide':dialog.querySelector('.m8-lens')?.remove();break;case'tile':m8SelectTile(Number(id));break;case'wire':m.turns[Number(id)]=(m.turns[Number(id)]+1)%4;m.tested=false;m.hint='模块已旋转，重新通电看线路。';paintMini();break;case'wireTest':m.tested=true;sound.effect('equipment');m.hint=M8.wireState(m.turns).connected?'电流到达风扇，模拟温度已下降。':'亮起的线路到这里停住了。检查亮线边上的接口方向。';paintMini();break;case'block':m.selected=id;paintMini();break;case'slide':m8Slide(Number(id));break;case'undo':m.moves.pop();m.hint='已撤回上一步，没有额外资源变化。';paintMini();break;case'card':m8Flip(Number(id));break;case'hint':m8Hint(m);break;case'done':miniComplete();break;case'delegate':miniComplete(true);break;case'skip':miniComplete(false,true);break;}}catch(err){m.hint=err.message;paintMini();}},true);
document.addEventListener('pointerdown',e=>{if(!miniDraft||modalKind!=='mini')return;const el=e.target.closest?.('[data-m8]');if(!el||!['lensHandle','block'].includes(el.dataset.m8)||el.disabled)return;m8Gesture={el,id:e.pointerId,startX:e.clientX,startY:e.clientY,kind:el.dataset.m8,block:el.dataset.id,moved:false};el.setPointerCapture?.(e.pointerId);},true);
document.addEventListener('pointermove',e=>{if(!miniDraft||modalKind!=='mini'){m8Gesture=null;return;}if(m8Gesture&&m8Gesture.id===e.pointerId){const g=m8Gesture;if(Math.hypot(e.clientX-g.startX,e.clientY-g.startY)>8)g.moved=true;if(g.kind==='lensHandle'){e.preventDefault();m8LensAt(e.clientX,e.clientY);}return;}if(e.pointerType!=='touch'&&e.target.closest?.('.m8-paper'))m8LensAt(e.clientX,e.clientY,e.target);},true);
document.addEventListener('pointerup',e=>{const g=m8Gesture;if(!g||g.id!==e.pointerId)return;m8Gesture=null;g.el.releasePointerCapture?.(e.pointerId);if(!g.moved)return;m8IgnoreClick=true;setTimeout(()=>{m8IgnoreClick=false;},0);if(g.kind==='block'&&miniDraft?.id==='box'&&modalKind==='mini'){const b=M8.slideSession(miniDraft.moves).blocks.find(b=>b.id===g.block);const delta=b.axis==='x'?e.clientX-g.startX:e.clientY-g.startY;if(Math.abs(delta)>20){miniDraft.selected=g.block;m8Slide(delta>0?1:-1);}}},true);
document.addEventListener('pointercancel',()=>{m8Gesture=null;},true);
document.addEventListener('keydown',e=>{if(!miniDraft||modalKind!=='mini')return;const button=e.target.closest?.('[data-m8]');if(!button||!['ArrowUp','ArrowRight','ArrowDown','ArrowLeft'].includes(e.key))return;const d={ArrowUp:-1,ArrowRight:1,ArrowDown:1,ArrowLeft:-1}[e.key];if(button.dataset.m8==='block'){const b=M8.slideSession(miniDraft.moves).blocks.find(x=>x.id===button.dataset.id);if(b&&(b.axis==='x'&&['ArrowLeft','ArrowRight'].includes(e.key)||b.axis==='y'&&['ArrowUp','ArrowDown'].includes(e.key))){e.preventDefault();e.stopImmediatePropagation();miniDraft.selected=b.id;m8Slide(d);}return;}const size=button.dataset.m8==='tile'?6:button.dataset.m8==='wire'?4:0;if(size){e.preventDefault();e.stopImmediatePropagation();const i=Number(button.dataset.id),next=i+(['ArrowUp','ArrowDown'].includes(e.key)?size*d:d);if(next>=0&&next<size*size&&(['ArrowUp','ArrowDown'].includes(e.key)||Math.floor(next/size)===Math.floor(i/size)))dialog.querySelector('[data-m8="'+button.dataset.m8+'"][data-id="'+next+'"]')?.focus();}},true);
