function startScreen(){let saved=null;try{saved=JSON.parse(localStorage.getItem(KEY)||'null');}catch{}$('#app').innerHTML=`<main class="start start-v8"><div class="start-visual"><img src="${motionAssetV8('cover-team-v8')}" alt="华东智行总裁与项目团队在总部门厅" fetchpriority="high"><div class="start-signature"><p>带着自己的判断，走向海外。</p><small>苏州 · 华东智行总部</small></div></div><section class="start-content"><div class="kicker">HUADONG INTELLILINK</div><h1>华东智行<br>出海决策室</h1><p class="intro">一份海外邀约，带来订单，也带来对公司核心的试探。你将带领华东智行，在技术、资金与信任之间，决定下一步。</p>${saved?.version===8?B('继续上次经营','continue','','primary'):''}${B(saved?'开始新的一轮':'走进苏州总部','new','','primary')}${B('了解经营方式','help','','ghost')}<div class="toolbar">${B('设置与存档','settings','','ghost')}${B('课程与来源','sources','','ghost')}</div><p class="source">V8 · 独立经营存档<br>人物、事件与经营数据为教学模拟。</p></section></main>`;}
function introCinema(){disposeV8Film();modal('新加坡的邀约到了',`<div class="v8-opening"><img src="${motionAssetV8('boardroom-v8')}" alt="晨光中的董事会会议室"><article class="opening-paper"><div class="news-masthead">商界观察 <small>产业专刊</small></div><p>苏州 · 企业出海</p><h1>华东智行筹备新加坡试点</h1><p class="paper-deck">客户希望尽快看到产品。核心能开放多少，要由你和团队一起定下来。</p><div class="paper-cols"><p>深圳的设备、成都的算法，正在准备新的市场机会。当地伙伴新智链希望合作，具体的人手、价格和技术范围还需要谈清楚。</p><p>这轮出海专项资金为80万元。你需要用实际调查、现场验证与商业决定，判断这条路是否值得继续。</p></div><small>剧情中的上市与股市属于虚构设定。</small><button class="btn primary full" data-v8-motion="board">放下晨报，开会商讨</button></article></div>`,{wide:true,kind:'intro',kicker:'第一幕 · 苏州总部'});sound.effect('paper');}
