function v8FilmMarkup(title,detail){return `<div class="v8-sign-shot"><img src="${motionAssetV8('boardroom-v8')}" alt="总裁确认决定的会议室"><div class="v8-sign-actor" id="v8-sign-actor" style="background-image:url('${motionAssetV8('ceo-signing-v8')}')"></div><div class="v8-signed-note"><small>本次决定</small><h3>${esc(title)}</h3><p>${esc(detail)}</p></div></div><div class="v8-dialogue"><div class="v8-speaker">总裁<small>决定已经记录</small></div><p>我已经确认这次安排。让团队按刚才定下的范围推进。</p></div><div class="v8-film-controls"><button class="btn ghost" data-v8-motion="filmSkip">跳过演出，查看反馈</button></div>`;}
function playV8Decision(old,a,done){disposeV8Film();const t=C.taskById[a.id],event=C.eventById[a.id],title=t?.title||event?.title||(a.type==='acceptOffer'?'确认合作条件':'确认经营安排'),cash=Math.round((S.cash-old.cash)*100)/100;modal('决定已确认',v8FilmMarkup(title,(cash?'本次现金'+(cash>0?'增加':'支出')+Math.abs(cash)+'万元。':'本次没有现金收付。')+(S.phase==='day'?'今天还剩'+S.slots+'次行动。':'本日行动已经结束，接下来进入夜间安排。')),{wide:true,kind:'v8-film',kicker:'演出可跳过，决定不重复结算'});v8FilmDone=()=>{const cb=done;v8FilmDone=null;disposeV8Film();if(dialog.open&&modalKind==='v8-film')close();cb?.();};let frame=0;const draw=()=>{const el=$('#v8-sign-actor');if(el)el.style.backgroundPosition=(frame%4)*100/3+'% '+Math.floor(frame/4)*100+'%';};draw();if(v8Reduce){frame=7;draw();v8FilmTimer=setTimeout(()=>v8FilmDone?.(),50);return;}sound.effect('paper');v8FilmFrameTimer=setInterval(()=>{frame=Math.min(7,frame+1);draw();if(frame===3)sound.effect('stamp');if(frame===6)sound.effect('paper');},420);v8FilmTimer=setTimeout(()=>v8FilmDone?.(),3400);}
const afterBeforeMotionV8=afterAction;
